create or replace function public.projects_project_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if exists (
    select 1
    from public.org_members m
    join public.orgs o on o.id = new.org_id
    where m.user_id = auth.uid()
      and m.org_id = o.id
      and m.role = 'admin'
  ) then
    return new;
  end if;

  raise exception 'only an org admin can manage % events on projects in org %', tg_op, new.org_id
     using errcode = '42501', detail = 'you are not a member of organization ID ' || new.org_id;

  return null;
end;
$$;

