create or replace function public.avatar_path_should_be_self()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user_uuid uuid := auth.uid();
begin
  if v_user_uuid is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if new.name is null or left(new.name, 0) = '/' then
    return new;
  end if;
  if split_part(new.name, '/', 1) <> v_user_uuid::text then
    raise exception 'Avatar path must start with current user id' using errcode = '42501';
  end if;
  return new;
end;
$$;

