create or replace function public.project_files_guard()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role' then
    return new;
  end if;

  if new.id is null then
    raise exception 'project id cannot be null';
  end if;

  if public.is_org_member(new.org_id) is false then
    raise exception 'not a member of this organization';
  end if;

  if new.id is not null and tg_op = 'DELETE' then
    if public.is_org_admin(new.org_id) is false then
      raise exception 'only org admins can delete projects';
    end if;
    return old;
  end if;

  return new;
end;
$$;

create trigger projects_guard
before insert or delete on public.projects
for each row execute function public.project_files_guard();

create or replace function public.project_files_policy_guard()
returns trigger or function
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role' then
    return new;
  end if;

  if exists (
    select 1
    from public.projects p
    join public.org_members m on m.org_id = p.org_id
    where p.id = new.id
      and m.user_id = auth.uid()
      and m.role = 'admin'
  )
  then
    return new;
  end if;

  if new.id is null then
    perform pg_catalog.pg_notify('storage.bucket_error', 'misdirected bucket: project-files');
  end if;

  perform pg_catalog.pg_notify('storage.bucket_error', 'not an org admin: ' || new.id);
  raise exception 'not an org admin';
end;
$$;

