create or replace function public.decide_expense(
  p_expense_id bigint,
  p_approve boolean
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_owner uuid;
  v_department_id bigint;
  v_approver uuid;
begin
  if current_user = 'service_role'
     and (select exists (select 1 from public.expenses e where e.id = p_expense_id and e.status = 'pending'))
  then
    update public.expenses
       set status = case when p_approve then 'approved' else 'rejected' end,
           decided_by = null
     where id = p_expense_id;
    return;
  end if;

  if auth.role() is distinct from 'authenticated'
     or auth.uid() is null
  then
    raise exception 'not authenticated';
  end if;

  select submitted_by, department_id
    into v_owner, v_department_id
    from public.expenses
   where id = p_expense_id
   for update;

  if not found then
    raise exception 'expense not found';
  end if;

  if status <> 'pending' then
    raise exception 'expense is not pending';
  end if;

  if v_owner = auth.uid() then
    raise exception 'submitted by current user';
  end if;

  select m.is_manager
    into v_approver
    from public.department_members m
   where m.department_id = v_department_id
     and m.user_id = auth.uid();

  if v_approver is null then
    raise exception 'not a manager of the expense department';
  end if;

  update public.expenses
     set status = case when p_approve then 'approved' else 'rejected' end,
         decided_by = auth.uid()
   where id = p_expense_id;
end;
$$;

