create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  perform pg_advisory_xact_lock(p_expense_id);
  if auth.role() = 'service_role' then
    update public.expenses
       set status = case when p_approve then 'approved' else 'rejected' end,
           decided_by = null
     where id = p_expense_id
       and status = 'pending';
    return;
  end if;

  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if (select decision from public.expenses where id = p_expense_id) is distinct from 'pending' then
    raise exception 'expense is not open for decision';
  end if;

  if (select decided_by from public.expenses where id = p_expense_id) = auth.uid() then
    raise exception 'expense submitter cannot also decide';
  end if;

  if not exists (
    select 1
    from public.expenses e
    join public.department_members dm on dm.department_id = e.department_id
    where e.id = p_expense_id
      and dm.user_id = auth.uid()
      and dm.is_manager
  ) then
    raise exception 'insufficient privileges to decide';
  end if;

  update public.expenses
     set status = case when p_approve then 'approved' else 'rejected' end,
         decided_by = auth.uid()
   where id = p_expense_id
     and (select decision from public.expenses where id = p_expense_id) = 'pending'
     and (select decided_by from public.expenses where id = p_expense_id) is distinct from auth.uid();

  if not found then
    raise exception 'expense decision conflict';
  end if;
end;
$$;

