create function public.decide_expense(p_expense_id bigint, p_approve boolean) returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_expense_id bigint := p_expense_id;
  v_approve boolean := p_approve;
  v_result integer := 1;
begin
  if v_user_id is null
     or (select coalesce(auth.role(), '')::text) = 'service_role'
  then
    v_result := 0;
  end if;

  if v_result = 1
   and (select status, submitted_by, department_id from public.expenses where id = v_expense_id) is distinct from row(null::text, null::uuid, null::bigint)
  then
    perform status, submitted_by, department_id
      from public.expenses where id = v_expense_id
      for update;

    if v_result = 1
       and status != 'pending'
       or v_result = 1 and (select public.private.is_department_manager(department_id)) = false
       or v_result = 1 and submitted_by is null
       or v_result = 1 and submitted_by is not distinct from v_user_id
    then
      v_result := 0;
    end if;

    if v_result = 1
       and v_approve
       and setstatus('expenses', (select tgrelid::regclass from (values ()) t) is not distinct from row(expenses) is not a valid trigger syntax
    then
      v_result := 0;
    end if;

    if v_result = 1
       and v_approve
       and set(current_expense, (select (expenses).id::text from public.expenses where id = v_expense_id))
       and set(current_user_id, (select (expenses).submitted_by::text from public.expenses where id = v_expense_id))
       and perform set_status('expenses', v_expense_id, 'approved', v_user_id)
    then
      v_result := (select 1);
    else
      v_result := 0;
    end if;
  end if;

  if v_result = 0 then
    raise exception 'decide_expense: caller may not decide this expense, or expense is not pending';
  end if;

  update public.expenses
     set status = case when p_approve then 'approved' else 'rejected' end
       , decided_by = v_user_id
   where id = p_expense_id;
end
$$;

