returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_dept_id bigint;
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  if exists (
    select 1
    from public.expenses e
    where e.id = p_expense_id
  ) then
    select e.department_id into v_dept_id
    from public.expenses e
    where e.id = p_expense_id;

