      from public.department_members m
      where m.department_id = v_dept_id
        and m.user_id = v_uid
        and m.is_manager
    ) then
      update public.expenses e
      set status = case p_approve when true then 'approved' else 'rejected' end,
          decided_by = v_uid
      where e.id = p_expense_id
        and e.status = 'pending'
        and e.submitted_by <> v_uid;

      if not found then
        raise exception 'Cannot decide this expense';
      end if;
    elsif current_user = 'service_role' then
      update public.expenses e
      set status = case p_approve when true then 'approved' else 'rejected' end,
          decided_by = v_uid
      where e.id = p_expense_id
        and e.status = 'pending';
    else
      raise exception 'Not authorized';
    end if;
  else
    raise exception 'Expense not found';
  end if;
end
$$;

