security invoker
set search_path = public, pg_temp
as $$
begin
  if new.id is distinct from old.id
     or new.department_id is distinct from old.department_id
     or new.submitted_by is distinct from old.submitted_by then
    raise exception 'Expense identity cannot be changed';
  end if;

  if new.status <> old.status or new.decided_by is distinct from old.decided_by then
    raise exception 'Expense decision state can only be set by decision events';
  end if;

  return new;
end
$$;

