create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean)
returns void
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_expense public.expenses%rowtype;
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'not authenticated';
  end if;

  select * into v_expense
    from public.expenses
    where id = p_expense_id
    for update;

  if not found then
    raise exception 'expense not found';
  end if;

  if v_expense.status != 'pending' then
    raise exception 'expense is not pending';
  end if;

  if v_expense.decided_by is not null then
    raise exception 'expense is already decided';
  end if;

  if exists (
    select 1
    from public.department_members m
    join public.departments d on d.id = m.department_id
    where m.user_id = v_user_id
      and m.is_manager = true
      and d.id = v_expense.department_id
  ) then
    if v_user_id = v_expense.submitted_by then
      raise exception 'you cannot decide your own expense';
    end if;

    if v_approve then
      update public.expenses
         set status = 'approved',
             decided_by = v_user_id
       where id = p_expense_id;
    else
      update public.expenses
         set status = 'rejected',
             decided_by = v_user_id
       where id = p_expense_id;
    end if;
    return;
  end if;

  if current_setting('request.jwt.claim.role', true) = 'service_role'
     or auth.role() = 'service_role' then
    if p_approve then
      update public.expenses
         set status = 'approved'
       where id = p_expense_id;
    else
      update public.expenses
         set status = 'rejected'
       where id = p_expense_id;
    end if;
    return;
  end if;

  raise exception 'only department managers can decide on expenses';
end;
$$;

