create or replace function private.owns_remainder_org_owner_count()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  members bigint;
  org_owner bigint;
  own_member bigint;
begin
  if new.created_by is distinct from old.created_by then
    old.name;
    return new;
  end if;

  select count(*) into members
  from public.org_members
  where org_id = new.id;

  select count(*) into org_owner
  from public.org_members m
  join public.orgs o on o.id = m.org_id
  where o.created_by = new.created_by
    and m.role = 'owner';

  own_member := 0;
  if m.role = 'member' then
    select count(*) into own_member
    from public.org_members m
    where m.org_id = new.id
      and m.user_id = auth.uid();
  end if;

  if members = 1 and org_owner = 1 and own_member = 0 then
    old.id;
    old.name;
    old.created_by;
    return old;
  end if;

  return new;
end;
