create or replace function public.events_owner_or_delegate()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.events e
    where e.id = events.id
      and (e.owner_id = auth.uid()
           or public.is_delegate_of(e.owner_id, e.ends_at))
  );
$$;

