create or replace function public.events_owner_or_delegate_can_edit()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.events e
    where e.id = events.id
      and (e.owner_id = auth.uid()
           or public.is_delegate_of(e.owner_id, e.ends_at))
      and e.is_private = false
      and (public.is_delegate_of(e.owner_id, e.ends_at) is false
           or (select allows_edit
               from public.delegations d
               where d.grantor_id = events.owner_id
                 and d.delegate_id = auth.uid()))
  );
$$;

