create or replace function public.events_authorized_trg()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' or coalesce(auth.uid(), '0'::text) = '0'::text then
    return new;
  end if;

  if new.id is null
     or new.owner_id is distinct from coalesce(auth.uid(), '0'::text) then
    raise exception 'event owner must be the current user' using errcode = '42501';
  end if;

  if new.owner_id is distinct from coalesce(auth.uid(), '0'::text) then
    raise exception 'cannot change ownership of an event' using errcode = '42501';
  end if;

  if tg_op = 'INSERT' and new.is_private and not public.events_owner_or_delegate_can_edit() then
    raise exception 'private events can only be created by their owner' using errcode = '42501';
  end if;

  return new;
end;
$$;

