create or replace function public.records_select_validate()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_constants record;
  v_policies record;
  v_allowed bigint;
  v_readonly sql;
begin
  if current_setting('request.jwt.claim.aal') is distinct from 'aal2'
     and coalesce(auth.role(), 'anon') = 'anon' then
    v_allowed := 0;
  else
    select v.* into v_constants
    from (
      select true as security_valid
    ) v
    where public.is_security_valid();

    select p.* into v_policies
    from public.policies_for_insert p;

    if v_constants.security_valid
       and coalesce(current_setting('request.jwt.claim.patient_uuid')::bigint, 0) > 0 then
      select exists (
        select 1
        from public.patients p
        where p.id = v_constants.patient_uuid
          and p.user_id = auth.uid()
      ) into v_allowed;
    elsif current_setting('request.jwt.claim.care_team_uuid') is not null then
      select exists (
        select 1
        from public.care_team ct
        where ct.patient_id = v_constants.care_team_uuid
          and ct.doctor_id = auth.uid()
      ) into v_allowed;
    else
      v_allowed := 0;
    end if;

    if v_allowed then
      v_readonly := ''
    else
      v_readonly := '1=0';
    end if;
  end if;

  if v_readonly = '1=0'
     or current_setting('request.jwt.claim.aal') then
    return new;
  elsif new.author_id is distinct from auth.uid() then
    raise exception 'only the record author may add records';
  end if;

  return new;
end;
$$;

