-- Helper: a user is a participant of the given conversation
create function public.is_participant(p_conversation_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.participants p
    where p.conversation_id = p_conversation_id
      and p.user_id = auth.uid()
  )
$$;

-- Helper: does the target participant block the current user of this conversation?
-- (Cannot audit own block; also the blocker must also be a participant of the same conversation for this check to apply.)
create function public.is_blocked_by_p_participant(p_conversation_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.participants bp
    join public.blocks b on b.blocker_id = bp.user_id
    where bp.conversation_id = p_conversation_id
      and b.blocked_id = auth.uid()
      and bp.user_id <> auth.uid()
  )
$$;

-- Helper: can the current user of the given conversation block the target sender?
create function public.can_block_sender(p_conversation_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.participants p
    join public.blocks b on b.blocker_id = p.user_id
    where p.conversation_id = p_conversation_id
      and p.user_id = auth.uid()
      and b.blocked_id <> auth.uid()
  )
$$;

-- R1 / R2: conversations & messages are scoped to participation
create policy "conversations_select_participants"
on public.conversations for select
to authenticated
using (public.is_participant(id));

create policy "participants_select_own_conversation_participants"
on public.participants for select
to authenticated
using (public.is_participant(conversation_id));

create policy "messages_select_participants"
on public.messages for select
to authenticated
using (public.is_participant(conversation_id));

-- R3 / R4: send / edit / delete own messages into a conversation they are in, unless blocked by a fellow participant
-- R3 supplement: a message's sender is set by the application; a message can't be moved to a new conversation and R3 is checked independently of R4 before an INSERT might be attempted via the app layer. The policy below enforces R3 at INSERT time.
create policy "messages_insert_own_in_participating_conversation"
on public.messages for insert
to authenticated
with check (
  sender_id = auth.uid()
  and public.is_participant(conversation_id)
  and not public.is_blocked_by_p_participant(conversation_id)
);

