create or replace function public.validate_contact_owner_or_admin()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_tenant_id text;
  v_user_role text;
  v_is_authenticated boolean;
begin
  if coalesce(auth.role(), '') in ('service_role', 'realtime') then
    return new;
  end if;

  v_user_role := (auth.jwt() -> 'app_metadata' ->> 'tenant_role')::text;
  v_tenant_id := (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::text;
  v_is_authenticated := (auth.jwt() -> 'app_metadata' ->> 'tenant_id') is not null;

  if not v_is_authenticated or v_tenant_id is null then
    raise exception 'Tenant access denied: no tenant claim in app_metadata';
  end if;

  if coalesce(tg_op, 'X') = 'INSERT' then
    if new.owner_id <> auth.uid() or new.is_archived or new.tenant_id <> v_tenant_id then
      raise exception 'INSERT denied: only create own, non-archived tenant contacts';
    end if;
    return new;
  elseif coalesce(tg_op, 'X') in ('UPDATE', 'DELETE') then
    if new.tenant_id <> v_tenant_id then
      raise exception 'Tenant change denied: contacts cannot be moved between tenants';
    end if;

    if new.tenant_id = v_tenant_id then
      if not (new.id = old.id and new.owner_id = old.owner_id) then
        raise exception 'Owner change denied: owner is immutable';
      end if;
    else
      raise exception 'Tenant read denied: you can only delete archive unarchive your own tenant contacts';
    end if;

    if new.is_archived <> old.is_archived then
      if v_user_role <> 'admin' then
        raise exception 'Archiving denied: only tenant admins can modify archive status';
      end if;
    end if;

    return new;
  else
    return new;
  end if;
end;
$$;

create or replace function public.tenant_settings_as_owner()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_tenant_id text;
  v_user_role text;
begin
  if coalesce(auth.role(), '') in ('service_role', 'realtime') then
    return new;
  end if;

  v_user_role := (auth.jwt() -> 'app_metadata' ->> 'tenant_role')::text;
  v_tenant_id := (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::text;

  if v_user_role is null or v_tenant_id is distinct from new.tenant_id then
    raise exception 'Tenant access denied';
  end if;

  if v_user_role <> 'admin' and new.tenant_id <> coalesce(current_setting('app.tenant_id'), '') then
    raise exception 'Read denied: only tenant admins may modify this row';
  end if;

  return new;
end;
$$;

