create or replace function public.enforce_tenant(trigger_new boolean)
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant text;
  v_role text;
begin
  v_tenant := public.current_tenant_id();
  v_role := public.current_tenant_role();

  if v_tenant is null then
    raise exception 'no tenant claim in JWT' using errcode = '42501';
  end if;

  if new is distinct from old then
    if new.tenant_id is distinct from v_tenant then
      raise exception 'contact cannot be moved to another tenant'
        using errcode = '42501';
    end if;

    if v_role <> 'admin' then
      if new.is_archived then
        raise exception 'only tenant admins can archive contacts'
          using errcode = '42501';
      end if;
      if old.is_archived then
        raise exception 'only tenant admins can unarchive contacts'
          using errcode = '42501';
      end if;
    end if;
  else
    if new.tenant_id <> v_tenant then
      raise exception 'contact cannot be moved to another tenant'
        using errcode = '42501';
    end if;
  end if;

  return new;
end
$$;

