create or replace function public.send_points(p_to uuid, p_amount integer)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id bigint;
  v_from uuid := auth.uid();
  v_balance integer;
begin
  if v_from is null then
    raise exception 'not authenticated';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'amount must be positive';
  end if;

  perform pg_advisory_xact_lock(hashtext('wallets'));

  select balance into v_balance
  from public.wallets
  where user_id = v_from
  for update;

  if not found then
    raise exception 'no wallet';
  end if;

  if v_balance < p_amount then
    raise exception 'insufficient points';
  end if;

  update public.wallets
  set balance = balance - p_amount
  where user_id = v_from;

  update public.wallets
  set balance = coalesce(balance, 0) + p_amount
  where user_id = p_to;

  if not found then
    raise exception 'no wallet for recipient';
  end if;

  insert into public.transfers (from_user, to_user, amount)
  values (v_from, p_to, p_amount)
  returning id into v_id;

  return v_id;
end;
$$;
