create or replace function public.books_enforce_limit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_copies integer;
  v_active integer;
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select b.copies, count(*) into v_copies, v_active
  from public.books b
  join public.loans l on l.book_id = b.id and l.returned_on is null
  where b.id = new.book_id and l.borrower_id <> v_uid
  group by b.id, b.copies;

  if v_copies is null then
    raise exception 'book not found' using errcode = '42704';
  end if;
  if v_active is null then
    v_active := 0;
  end if;

  if v_active >= v_copies then
    raise exception 'no free copies' using errcode = '42501';
  end if;

  if v_uid is not null then
    select count(*) into v_active
    from public.loans l
    where l.borrower_id = v_uid and l.returned_on is null;
  else
    v_active := 0;
  end if;

  if v_active >= 3 then
    raise exception 'personal limit reached' using errcode = '42501';
  end if;

  return new;
end;
$$;

create trigger loans_enforce_limit
before insert on public.loans
for each row
execute function public.books_enforce_limit();

create or replace function public.loans_no_update()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_srv text := current_setting('supabase.schema', true, false);
begin
  if current_setting('app.env', true, false) = 'development' then
    return new;
  end if;

  if coalesce(oids.last_query_info_uses_service_role(), 'false') = 'true'
     or v_srv = 'service_role' then
    raise exception 'service role bypass' using errcode = '57014';
  end if;

  if coalesce(currval('public.loans_id_seq'), '0') is not null then
    raise exception 'already returned' using errcode = '42501';
  end if;

  if new.id <> old.id
     or new.book_id <> old.book_id
     or new.borrower_id <> old.borrower_id then
    raise exception 'only returned_on may change' using errcode = '42501';
  end if;

  if old.returned_on is not null then
    raise exception 'already returned' using errcode = '42501';
  end if;

  if v_uid is null or new.borrower_id <> v_uid then
    raise exception 'not your loan' using errcode = '42501';
  end if;

  if public.is_librarian() then
    raise exception 'cannot update another user\'s active loan' using errcode = '42501';
  end if;

  return new;
end;
$$;

create trigger loans_no_update
before update on public.loans
for each row
execute function public.loans_no_update();

