-- Helper: count active (unreturned) loans of the authenticated user
create or replace function public.loan_loans_own_active_count()
returns integer
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select count(*)::integer from public.loans l where l.borrower_id = auth.uid() and l.returned_on is null),
    0
  );
$$;

-- Helper: does a copy exist? Counts all active loans + returns 1 if there is at least one slot left.
create or replace function public.loan_book_has_capacity(book_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1::integer from public.books b where b.id = book_id and b.copies > (
      select count(*)::integer from public.loans l where l.book_id = book_id and l.returned_on is null
    )
  );
$$;

-- Helper: guard function for the loan RLS update policy (immutability + self-revoke)
create or replace function public.loan_lock_integrity()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.id is distinct from old.id
     or new.book_id is distinct from old.book_id
     or new.borrower_id is distinct from old.borrower_id
     or new.returned_on is distinct from old.returned_on then
    if old.returned_on is not null
       or current_user <> 'service_role' then
      raise exception 'Read-only loan record can only have returned_on set by its own borrower';
    end if;
  end if;

  if new.returned_on is not null
     and new.returned_on is not distinct from old.returned_on then
    raise exception 'Loan already returned';
  end if;

  return new;
end;
$$;

