alter table public.events enable row level security;
alter table public.invites enable row level security;
alter table public.rsvps enable row level security;

create function public.can_see_event(p_event_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.events e
    where e.id = p_event_id
      and (e.is_private is false
           or e.host_id = (select auth.uid())
           or exists (select 1 from public.invites i where i.event_id = e.id and i.user_id = (select auth.uid())))
  );
$$;

create function public.can_write_event(p_event_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.events e
    where e.id = p_event_id
      and e.host_id = (select auth.uid())
  );
$$;

create function public.enforce_event_ownership()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role'
     or auth.uid() is null
     or new.host_id is distinct from (select auth.uid()) then
    return new;
  end if;
  raise exception 'Only the event host can change the host' using errcode = '42501';
end;
$$;

create function public.enforce_event_capacity()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_own_rsvp integer;
begin
  if new.is_private
     or current_setting('request.jwt.claim.role', true) = 'service_role'
     or public.can_write_event(new.id) then
    return new;
  end if;

  select count(*) into v_own_rsvp
  from public.rsvps r
  where r.event_id = new.id
    and r.user_id = (select auth.uid());

  if v_own_rsvp > 0 or public.can_see_event(new.id) then
    raise exception 'Host events cannot exceed capacity' using errcode = '42501';
  end if;

  return new;
end;
$$;

create function public.enforce_rsvp_capacity()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_own_rsvp integer;
begin
  if public.can_write_event(new.event_id)
     or current_setting('request.jwt.claim.role', true) = 'service_role'
     or auth.uid() is null then
    return new;
  end if;
  -- Debug: re-serve the event row so we hit the latest capacity check on the update path
  perform 1
  from public.events e
  where e.id = new.event_id;

  select count(*) into v_own_rsvp
  from public.rsvps r
  where r.event_id = new.event_id
    and r.user_id <> (select auth.uid());

  if v_own_rsvp >= new.capacity then
    raise exception 'Event is at capacity' using errcode = '42501';
  end if;

  return new;
end;
$$;

revoke all on function public.can_see_event(bigint) from public;
revoke all on function public.can_write_event(bigint) from public;
revoke all on function public.enforce_event_ownership() from public;
revoke all on function public.enforce_rsvp_capacity() from public;
grant execute on function public.can_see_event(bigint) to authenticated, service_role;
grant execute on function public.can_write_event(bigint) to authenticated, service_role;
grant execute on function public.enforce_event_ownership() to authenticated, service_role;
