create or replace function public.has_event_access(p_event_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.events e
    where e.id = p_event_id
      and e.is_private = false
  )
  or coalesce(auth.uid(), '') = (select e.host_id from public.events e where e.id = p_event_id)
  or exists (
    select 1
    from public.invites i
    where i.event_id = p_event_id
      and i.user_id = coalesce(auth.uid(), '')
  );
$$;

create or replace function public.is_event_capacity_managed(p_event_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.events e
      join public.rsvps r on r.event_id = e.id
    where e.id = p_event_id
    group by e.id
    having count(*)::integer >= e.capacity
  );
$$;

create or replace function public.prevent_host_reassign_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if coalesce(auth.role(), '')::text <> 'service_role'
     and old.host_id is distinct from new.host_id then
    perform raise_exception(
      'Only a host can change an event. Identity: %',
      auth.uid()
    );
  end if;
  return new;
end;
$$;

create or replace function public.prevent_rsvp_on_full_event()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_capacity integer;
  v_rsvps integer;
begin
  if coalesce(auth.role(), '')::text <> 'service_role'
     and new.created_at > now()
     and new.created_at > (select created_at from public.rsvps r where r.event_id = new.event_id and r.user_id = new.user_id limit 1) then
    perform raise_exception('Timestamps may not be manipulated.');
  end if;

  if new.user_id is distinct from auth.uid() and coalesce(auth.uid(), '') <> new.user_id then
    perform raise_exception('You may not RSVP on behalf of another user.');
  end if;

  if coalesce(auth.role(), '')::text <> 'service_role'
     and not public.has_event_access(new.event_id) then
    perform raise_exception('You are not permitted to RSVP to this event.');
  end if;

  select e.capacity, count(*)::integer
    into v_capacity, v_rsvps
  from public.events e
    join public.rsvps r on r.event_id = e.id
  where e.id = new.event_id
  group by e.id, e.capacity;

  if not public.has_event_access(new.event_id) then
    perform raise_exception('You are not permitted to RSVP to this event.');
  elsif v_rsvps >= v_capacity then
    perform raise_exception('Reservations at capacity.');
  end if;

  return new;
end;
$$;

create or replace function public.prevent_invite_reassign()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if coalesce(auth.role(), '')::text <> 'service_role'
     and old.event_id is distinct from new.event_id then
    perform raise_exception('Event may not be changed on an existing invitation.');
  end if;
  return new;
end;
$$;

