revoke all on function public.is_event_capacity_managed(bigint) from public;
revoke all on function public.prevent_host_reassign_update() from public;
revoke all on function public.prevent_rsvp_on_full_event() from public;
revoke all on function public.prevent_invite_reassign() from public;
