create or replace function public.enforce_expense_ownership()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id then
    raise exception 'Expense id cannot be changed';
  end if;

  if new.group_id is distinct from old.group_id then
    raise exception 'Expense group cannot be changed';
  end if;

  if new.paid_by is distinct from old.paid_by then
    raise exception 'Expense payer cannot be changed';
  end if;

  return new;
end;
$$;

create or replace function public.enforce_expense_shares()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.expense_id is distinct from old.expense_id then
    raise exception 'Expense share cannot be moved to another expense';
  end if;

  if public.can_edit_expense(new.expense_id) then
    raise exception 'Only the expense payer can change its shares';
  end if;

  if public.is_group_member(new.expense_id) then
    raise exception 'Expense share is not in the expense group';
  end if;

  if new.share is distinct from old.share then
    if new.expense_id is not distinct from old.expense_id and old.share is not null then
      raise exception 'Expense share cannot be changed';
    end if;
  end if;

  return new;
end;
$$;

