create or replace function public.enforce_expense_authority()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payer uuid;
  v_group bigint;
begin
  if tg_op = 'DELETE' then
    select paid_by, group_id into v_payer, v_group
    from public.expenses
    where id = old.id;
    if v_payer is null or v_payer is distinct from auth.uid() then
      raise exception 'only the expense payer can delete it' using errcode = '42501';
    end if;
    return old;
  end if;

  select paid_by, group_id into v_payer, v_group
  from public.expenses
  where id = new.id;

  if v_payer is null then
    raise exception 'expense payer cannot be set to null' using errcode = '42511';
  end if;

  if new.paid_by is distinct from auth.uid() then
    raise exception 'only the expense payer can edit it' using errcode = '42501';
  end if;

  if new.group_id is distinct from v_group then
    raise exception 'an expense cannot be moved to another group' using errcode = '42501';
  end if;

  return new;
end;
$$;

