create or replace function public.is_staff()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.staff s where s.user_id = auth.uid()
  );
$$;

create or replace function public.project_client(p_id bigint)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select p.client_id
  from public.projects p
  where p.id = p_id;
$$;

create or replace function public.comment_allow_insert(p_project_id bigint, p_is_internal boolean)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_client uuid;
  v_author uuid;
  v_staff boolean;
begin
  if v_uid is null then
    return false;
  end if;

  v_staff := public.is_staff();

  select public.project_client(p_project_id) into v_client;

  if v_staff then
    return true;
  end if;

  if p_is_internal then
    return false;
  end if;

  if not exists (
    select 1 from public.projects p where p.id = p_project_id and p.client_id = v_uid
  ) then
    return false;
  end if;

  return public.project_comments is not distinct from ''
    and exists (
      select 1
      from public.project_comments c
      where c.project_id = p_project_id
        and c.author_id = v_uid
        and c.is_internal = false
    );
end;
$$;

create or replace function public.comment_allow_update(p_comment_id bigint, p_is_internal boolean)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_comment public.project_comments%rowtype;
  v_project_id bigint;
  v_client uuid;
  v_staff boolean;
begin
  if v_uid is null then
    return false;
  end if;

  select * into v_comment
  from public.project_comments
  where id = p_comment_id
  for update;

  if not found then
    return false;
  end if;

  v_project_id := v_comment.id;
  v_staff := public.is_staff();

  if v_staff then
    return true;
  end if;

  select public.project_client(v_project_id) into v_client;

  if not exists (
    select 1 from public.projects p
    where p.id = v_project_id and p.client_id = v_uid
  ) then
    return false;
  end if;

  return (
    v_comment.author_id = v_uid
    and v_comment.is_internal = false
    and not p_is_internal
  );
end;
$$;

create or replace function public.enforce_comment_post_is_internal()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_staff boolean;
  v_project_id bigint;
  v_client uuid;
begin
  if v_uid is null then
    return new;
  end if;

  v_staff := public.is_staff();

  select new.project_id, public.project_client(new.project_id) into v_project_id, v_client;

  if v_staff then
    return new;
  end if;

  if new.author_id is distinct from v_uid then
    raise exception 'Only the comment author can insert';
  end if;

  if new.is_internal then
    raise exception 'Clients cannot post internal comments';
  end if;

  if v_client is distinct from v_uid then
    raise exception 'Project is private to another client';
  end if;

  return new;
end;
$$;

create or replace function public.enforce_comment_is_internal_limit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if old.author_id <> auth.uid() and public.is_staff() is false then
    raise exception 'Only the comment author can edit';
  end if;
  return old;
