create or replace function public.saved_searches_notify_valid(
  p_notify_email text
) returns boolean
language sql
immutable
as $$
  select coalesce(
    p_notify_email = '',
    p_notify_email is null,
    exists (
      select 1
      from auth.jwt()
      join auth.users u on u.email is not null
      where auth.jwt() ->> 'role' = 'authenticated'
        and lower(auth.jwt() ->> 'email') = lower(p_notify_email)
        and u.email is not null
    )
  );
$$;

create or replace function public.saved_searches_guard_notify()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if new.user_id is distinct from auth.uid()
     or pg_trigger_depth() > 0
     or current_user in ('service_role', 'postgres', '') then
    return new;
  end if;

  if coalesce(current_setting('request.jwt.claim.email', true), '') is null
     or public.saved_searches_notify_valid(new.notify_email) is distinct from true then
    raise exception 'notify_email must be the user\'s verified email'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

