```sql
alter table public.guestbook_entries enable row level security;

-- R1: Anyone can read approved entries.
-- R2 / R3: Signed-in visitors can read their own entries (any approval state).
-- Unapproved / unknown-author rows are visible only to the service role.
create policy guestbook_select on public.guestbook_entries
  for select to anon, authenticated
  using (
    is_approved = true or author_id = auth.uid()
  );

-- R2 / R3 / R4: Insert always fails if is_approved is true,
-- author does not match the current JWT subject, or the column is edited
-- in a way that violates R2 (no update path exists, so ON CONFLICT or
-- schema-trigger guard can be left as guard rails only).
create policy guestbook_insert on public.guestbook_entries
  for insert to anon, authenticated
  with check (
    is_approved = false
    and author_id is not distinct from auth.uid()
  );

-- R3: Signed-in visitors can delete their own entries (approved or not).
create policy guestbook_delete on public.guestbook_entries
  for delete to authenticated
  using (author_id = auth.uid());

-- R4: No update policy exists; rows are never updatable from the app.
-- Revoke update on the public table so even policy errors or ad-hoc SQL
-- result in a "permission denied" instead of silently applying changes.
revoke update on public.guestbook_entries from anon, authenticated;
grant update on public.guestbook_entries to service_role;

-- (Optional internal RLS guards: no anon / no authenticated policy ever
-- matches UPDATE, and even if a role defect or future schema change added
-- such a policy the guard below protects the data.)
create or replace function public.guestbook_no_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if current_user in ('service_role', 'pc_super', 'pg_read_all_data') then
    return new;
  end if;
  raise exception 'guestbook_entries cannot be updated via the app';
end;
$$;

create trigger guestbook_no_update
  before update on public.guestbook_entries
  for each row execute function public.guestbook_no_update();

-- R5: Service role keeps full access (RLS bypassed by pg_any_privileges).
revoke all on public.guestbook_entries from public;
revoke delete, update, truncate, references, trigger on public.guestbook_entries from anon, authenticated;
grant select, insert, delete on public.guestbook_entries to anon, authenticated;
grant all on public.guestbook_entries to service_role;

-- R5: Lock down the read tables used in the guestbook policies.
revoke all on public.auth_users from anon;
revoke insert, delete, truncate on public.auth_users from authenticated;
grant select on public.auth_users to authenticated, service_role;
```

