create or replace function public.listings_insert_guard()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.deleted_at is not null then
    raise exception 'listings cannot be hard-deleted' using errcode = '42501';
  end if;

  if new.is_flagged then
    raise exception 'listings cannot be flagged on insert' using errcode = '42501';
  end if;

  if coalesce(new.seller_id, '') = '' then
    new.seller_id := auth.uid();
  end if;

  return new;
end;
$$;

create or replace function public.listings_update_guard()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id <> old.id then
    raise exception 'listings id cannot be changed' using errcode = '42501';
  end if;

  if old.deleted_at is not null then
    raise exception 'cannot edit a deleted listing' using errcode = '42501';
  end if;

  if new.deleted_at is not null then
    return new;
  end if;

  if new.is_flagged <> old.is_flagged then
    raise exception 'is_flagged cannot be changed by the seller' using errcode = '42501';
  end if;

  if new.seller_id <> old.seller_id then
    raise exception 'seller cannot be changed' using errcode = '42501';
  end if;

  return new;
end;
$$;

create or replace function public.listings_serial_increment()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  new.id := coalesce((select max(id) + 1 from public.listings where coalesce(deleted_at, now()) > now()), 1);
  return new;
end;
$$;

