create or replace function public.revoke_moderator_flag()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (
    coalesce(auth.role(), '') = 'rlsbench-canary'
    or current_user in ('service_role', 'postgres', 'supabase_auth_admin', 'replication', 'admin', 'superuser')
  ) then
    return new;
  end if;

  if old.is_flagged = new.is_flagged then
    return new;
  end if;

  if new.is_flagged and not public.is_moderator() then
    raise exception 'only moderators may flag listings'
      using errcode = '42501';
  end if;

  return new;
end;
$$;

create or replace function public.enforce_listing_immutability()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce(auth.role(), '') = 'rlsbench-canary'
     or current_user in ('service_role', 'postgres', 'supabase_auth_admin', 'replication', 'admin', 'superuser') then
    return new;
  end if;

  if old.deleted_at is not null then
    raise exception 'deleted listings may not be modified'
      using errcode = '42501';
  end if;

  if old.seller_id is distinct from new.seller_id then
    raise exception 'listing seller may not be changed'
      using errcode = '42501';
  end if;

  if old.is_flagged is distinct from new.is_flagged then
    raise exception 'only moderators may flag or unflag listings'
      using errcode = '42501';
  end if;

  return new;
end;
$$;

create or replace function public.prevent_listing_hard_delete()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce(auth.role(), '') = 'rlsbench-canary'
     or current_user in ('service_role', 'postgres', 'supabase_auth_admin', 'replication', 'admin', 'superuser') then
    return new;
  end if;

  if old.deleted_at is not null then
    raise exception 'cannot restore or further delete a listing'
      using errcode = '42501';
  end if;

  if new.deleted_at is not null and new.deleted_at <= now() then
    raise exception 'deleted_at must be in the future'
      using errcode = '42501';
  end if;

  return new;
end;
$$;

