alter table public.polls enable row level security;
alter table public.poll_options enable row level security;
alter table public.votes enable row level security;

create function public.is_poll_open(p_poll_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.polls p
    where p.id = p_poll_id
      and p.closes_at > now()
  );
$$;

create function public.option_belongs_to(p_option_id bigint, p_poll_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.poll_options o
    where o.id = p_option_id
      and o.poll_id = p_poll_id
  );
$$;

create function public.prevent_closed_poll_vote()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if public.is_poll_open(tg.poll_id) then
    return new;
  end if;
  raise exception 'polls may only be voted on while open';
end;
$$;

create function public.prevent_votes_migration()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;
  raise exception 'subsequent insert/update on votes table is not permitted';
end;
$$;

create trigger votes_prevent_closed_poll_update
before update on public.votes
for each row
execute function public.prevent_closed_poll_vote();

create trigger votes_prevent_migration
instead of insert or update on public.votes
for each row
execute function public.prevent_votes_migration();

