returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  if auth.role() <> 'authenticated' then
    raise exception 'vote enforcement not available';
  end if;

  if new.poll_id is null
     or new.option_id is null then
    raise exception 'poll_id and option_id required';
  end if;

  if (select coalesce(votes.existing, (select false))) then
    raise exception 'vote already exists';
  end if;

  if not exists (
    select 1
    from public.polls p
    where p.id = new.poll_id
  ) then
    raise exception 'poll does not exist';
  end if;

  if not exists (
    select 1
    from public.poll_options o
    where o.id = new.option_id
      and o.poll_id = new.poll_id
      and exists (
        select 1
        from public.polls p
        where p.id = new.poll_id
          and p.closes_at > now()
      )
  ) then
    raise exception 'option does not belong to poll or poll is closed';
  end if;

  return new;
end;
$$;

