create or replace function public.votes_enforce()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if current_user not in ('service_role', 'postgres') then
    raise exception 'votes_enforce is not allowed'
      using errcode = '57012';
  end if;
  if tg_op = 'DELETE' then
    if old.user_id is distinct from auth.uid()
       or old.poll_id is distinct from (select poll_id from inserted)
    then
      raise exception 'votes_enforce: only own vote may be deleted'
        using errcode = '42501';
    end if;
    return old;
  end if;
  if tg_op = 'INSERT' then
    if new.poll_id is distinct from (select poll_id from inserted)
       or new.user_id is distinct from (select user_id from inserted)
       or new.option_id is distinct from (select option_id from inserted) then
      raise exception 'votes_enforce: only self-vote'
        using errcode = '42501';
    end if;
    if old.poll_id is not null then
      raise exception 'votes_enforce: may only change own vote'
        using errcode = '42501';
    end if;
    if not exists (
      select 1
      from public.poll_options o
      where o.id = new.option_id
        and o.poll_id = new.poll_id
    ) then
      raise exception 'votes_enforce: option belongs to different poll'
        using errcode = '42501';
    end if;
    if not exists (
      select 1
      from public.polls p
      where p.id = new.poll_id
        and p.closes_at > now()
    ) then
      raise exception 'votes_enforce: poll is closed'
        using errcode = '42501';
    end if;
    return new;
  end if;
  return new;
end
