create or replace function public.po_approved(p_po_id bigint, p_approver_id uuid)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_is_requester boolean;
  v_amount numeric(12, 2);
  v_limit numeric(12, 2);
begin
  if p_approver_id is null then
    return false;
  end if;

  select r.requester_id, p.amount
    into v_is_requester, v_amount
    from public.purchase_orders p
   join public.approvers a on a.user_id = p_approver_id
   join public.purchase_orders r on r.id = p_po_id
   where p.id = p_po_id;

  if not found then
    return false;
  end if;

  if v_is_requester then
    return false;
  end if;

  select a.limit_amount
    into v_limit
    from public.approvers a
   where a.user_id = p_approver_id;

  return v_amount <= v_limit;
end;
$$;

