returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.requester_id is distinct from old.requester_id
     or new.vendor is distinct from old.vendor
     or new.amount is distinct from old.amount then
    raise exception 'purchase orders cannot have their columns changed';
  end if;

  if old.decided_at is not null then
    raise exception 'decided purchase orders cannot be edited';
  end if;

  if new.requester_id <> auth.uid() then
    raise exception 'only the requester may edit this purchase order';
  end if;

  return new;
end;
$$;

