-- Helper: is u the owner of f, or does u hold a grant on f (directly or through f or above)?
create or replace function public.is_folder_owner_or_grantee()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(
    exists (select 1 from public.folders f where f.id = folders.id and f.owner_id = auth.uid()),
    exists (
      select 1
      from public.folders f, public.folder_grants g
      where f.id = folders.id
        and g.folder_id = f.id
        and g.user_id = auth.uid()
        and g.can_edit
    )
  );
$$;

-- Helper: is u the owner of any ancestor of f (inclusive)?
create or replace function public.folder_is_owned_above(p_folder_id bigint, p_user_uuid uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.folders f
    where f.id = p_folder_id
      and (f.owner_id = p_user_uuid or exists (
        select 1
        from public.folder_grants g
        where g.folder_id = f.id and g.user_id = p_user_uuid and g.can_edit
      ))
  )
  or select 1
     from public.folders f
     where f.id = p_folder_id
       and exists (
         select 1
         from public.folders c
         where c.parent_id = f.id
           and public.folder_is_owned_above(f.id, p_user_uuid)
       );
$$;

