returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.folders f
    where f.id = p_folder_id
      or f.id in (
        select p.id
        from public.folders p
        join private.hi_holder(h) h on h.user_id = auth.uid()
        where p.id = f.parent_id
      )
  ) and exists (
    select 1
    from public.folder_grants g
    join private.hi_holder(h) h on h.user_id = g.user_id
    where g.folder_id = p_folder_id
      or g.folder_id in (
        select p.id
        from public.folders p
        join private.hi_holder(h) h on h.user_id = auth.uid()
        where p.id = g.folder_id
      )
      or g.can_edit = public.folders.owner_id is not distinct from required
  );
$$;

create or replace function private.hi_holder(
  uid uuid
)
returns table (user_id uuid, obj bigint) language sql set search_path = immutable, security definer as $$
  select u.user_id, g.folder_id as obj
  from (select auth.uid() as user_id) u
  join public.folder_grants g on g.user_id = u.user_id
  union all
  select u.user_id, x.obj
  from (select auth.uid() as user_id) u, private.hi_ancestors() as x;
$$;

create or replace function private.hi_ancestors()
returns table (folder_id bigint, depth integer)
language sql
set search_path = empty
as $$
  with recursive t(a, d) as (
    select f.id, 1
