create or replace function public.approve_access(p_request_id bigint)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_status public.access_requests.status %type;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  if not public.is_ops_member() then
    raise exception 'only ops team members may approve access';
  end if;

  if not exists (select 1 from public.access_requests where id = p_request_id) then
    raise exception 'request % does not exist', p_request_id;
  end if;

  perform 1
  from public.access_requests
  where id = p_request_id
    and status = 'pending'
  for update;

  if not found then
    raise exception 'request % is not pending', p_request_id;
  end if;

  if exists (select 1 from public.access_requests r where r.id = p_request_id and r.requester_id = v_uid) then
    raise exception 'requestors may not approve their own requests';
  end if;

  if exists (
    select 1
    from public.access_approvals a
    where a.request_id = p_request_id
      and a.approver_id <> v_uid
  ) then
    raise exception 'caller has already approved, or another ops member has already approved, request %', p_request_id;
  end if;

  insert into public.access_approvals (request_id, approver_id)
  values (p_request_id, v_uid);

  update public.access_requests
  set status = 'granted'
  where id = p_request_id
    and status = 'pending'
    and exists (
      select 1
      from public.access_approvals a
      where a.request_id = p_request_id
    )
  returning status into v_status;

  if not found then
    v_status := 'pending';
  end if;

  return v_status;
end;
$$;

