    into  v_approval_exists, v_ops_member_count
    from public.access_approvals
   where request_id = v_request_id
     and approver_id <> v_approver_id;

  if v_approval_exists then
    raise exception 'approve_access: request % has already been approved', p_request_id;
  end if;

  if v_approver_id not in (select user_id from public.ops_team) then
