  insert into public.access_approvals (request_id, approver_id, approved_at)
  values (v_request_id, v_approver_id, now());

  update public.access_requests
     set status = 'granted'
   where id = v_request_id
     and status = 'pending'
     and exists (
       select 1
         from public.access_approvals
        where request_id = v_request_id
        group by approver_id
        having count(*) >= 2
     );

  if exists (
    select 1 from public.access_requests
   where id = v_request_id
     and status = 'granted'
  ) then
    return 'granted';
  else
    return 'pending';
  end if;
end;
