create function public.approve_access(p_request_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_requester uuid;
  v_status text;
begin
  perform pg_advisory_xact_lock(7573, p_request_id);
  select requester_id
    into v_requester
    from public.access_requests
   where id = p_request_id
     for update;
  if not found then
    raise exception 'request % does not exist', p_request_id;
  end if;
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if auth.uid() = v_requester then
    raise exception 'the requester can not approve their own request';
  end if;
  if public.approvals_added(p_request_id) then
    raise exception 'the caller has already approved this request';
  end if;
  if (select status from public.access_requests where id = p_request_id) != 'pending' then
    raise exception 'request % is not pending', p_request_id;
  end if;
  insert into public.access_approvals (request_id, approver_id)
  values (p_request_id, auth.uid());
  v_status := (select status from public.access_requests where id = p_request_id);
  if (select count(distinct approver_id) from public.access_approvals where request_id = p_request_id) >= 2 then
    update public.access_requests
       set status = 'granted'
     where id = p_request_id;
    v_status := 'granted';
  end if;
  return v_status;
end;
$$;

