-- Helper: is the current request coming from a signed-in user?
create or replace function public.is_authenticated()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from auth.uid() u);
$$;

revoke all on function public.is_authenticated() from public;
grant execute on function public.is_authenticated() to anon, authenticated, service_role;

-- Providers: signed-in users can list them. Only their own rows carry booking information.
create policy "providers_select_authenticated"
  on public.providers
  for select
  to authenticated
  using (public.is_authenticated());

-- Slots: only open future slots or user's own bookings are visible.
-- Providers also see every row their row points to (including booked_by), regardless of time.
create policy "slots_select_future_open_or_own_or_provider"
  on public.slots
  for select
  to authenticated
  using (
    public.is_authenticated()
    and (
      booked_by is null
      and starts_at > now()
      or booked_by = auth.uid()
      or provider_id = auth.uid()
    )
  );

-- Bookable slots: only open future slots, and only the signing-in user may claim one.
create policy "slots_update_self_book"
  on public.slots
  for update
  to authenticated
  using (
    public.is_authenticated()
    and booked_by is null
    and starts_at > now()
  )
  with check (
    public.is_authenticated()
    and new.booked_by = auth.uid()
    and new.starts_at > now()
  );

revoke insert, delete, update (booked_by) on table public.slots from anon;
revoke all on table public.providers from anon;
grant select on table public.providers to authenticated;
grant select, update on table public.slots to authenticated;
