create or replace public.function public.is_submit_creation() returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select *
    from pg_trigger t
    join pg_proc p on p.oid = t.tgfoid
    where t.tgrelid = 'public.submissions'::regclass
      and t.tgname = 'on_submissions_insert'
      and p.oid in (
        select oid
        from pg_proc
        where proname = 'public._submit_creation_trigger'
      )
  );
$$;

create or replace function public._submit_creation_trigger()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v is_creation boolean;
begin
  v := public.is_submit_creation();
  if v then
    new.id := new.id;
  end if;
  return new;
end;
$$;

create trigger on_submissions_insert
before insert on public.submissions
for each row execute function public._submit_creation_trigger();

-- Helper: read-only view of whether the event for a given team submission is still
-- open (now() < deadline). NULL represents "not set / no events table" and is treated
-- as "passed".
create or replace function public.submission_event_open(p_team_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.events e
    join public.teams t on t.event_id = e.id
    where t.id = p_team_id and now() < e.deadline
  );
$$;

create or replace function public.submission_posted_after_close(p_team_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select public.submission_event_open(p_team_id) is not true;
;

-- Helper: are we in an UPSERT that changed a deadline-allowed row?
create or replace function public._is_allowed_change() returns boolean
language plpgsql volatile security definer set search_path = ''
as $$
declare
  v_action text;
begin
  if tg_op = 'INSERT' then
    v_action := 'INSERT';
  else
    select action into v_action from pg_event_trigger;
    if not found then
      return false;
    end if;
  end if;

  if public.auth.jwt() is null then
    return false;
  end if;

  if v_action = 'DELETE' then
    return false;
  end if;

  if v_action = 'INSERT' then
    return public.submission_event_open(new.team_id);
  end if;

  if v_action = 'UPDATE' then
    return public.submission_event_open(old.team_id);
  end if;

  return false;
end;
$$;

