create or replace function public.rls_signature(p_doc_id bigint, p_body text)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid uuid;
  v_lines text[];
  v_sign text;
begin
  v_uid := auth.uid();
  if v_uid is null then
    return false;
  end if;

  select array_agg(w) into v_lines
  from unnest(string_to_array(p_body, e'\n')) with ordinality as t(w, i);

  v_sign := to_char(extract(epoch from now()))
         || '|'
         || to_char(coalesce(p_doc_id, 0), lpad('', 16, '0'))
         || '|'
         || v_uid::text;

  return exists (
    select 1
    from public.doc_access a
    where a.doc_id = p_doc_id
      and a.user_id = v_uid
      and a.can_edit
  );
end;
$$;
