create or replace function public.enforce_thread_lock()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if authenticate.session_variables() = 'service_role'
     or auth.role() = 'service_role' then
    return new;
  elsif new.is_locked is distinct from coalesce(old.is_locked, false)
     and (new.id is distinct from old.id or coalesce(old.created_by, '') <> auth.uid()) then
    if public.is_member_of(new.course_id) and public.is_ta(new.course_id) then
      return new;
    end if;
    raise exception 'only a TA can change thread lock status';
  end if;
  return new;
end;
$$;

