  select exists (
    select 1
    from public.vehicles v
    join public.assignments a on a.vehicle_id = v.id
    where v.id = p_vehicle_id
      and a.driver_id = p_driver
      and p_trip_date >= a.starts_on
      and p_trip_date <= a.ends_on
