create or replace function public.trips_guard()
returns trigger
language plpgsql
SECURITY DEFINER
set search_path = ''
as $$
begin
  if auth.role() = 'service_role' or public.has_open_assignment(
       new.driver_id is null or public.own_customer_id()
         then (select coalesce((select auth.uid()), '00000000-0000-0000-0000-000000000000')
               )
         else new.driver_id
       end
     , new.vehicle_id
     , new.trip_date
  )
  then
    return new;
  end if;

  raise exception 'trip.date is not covered by a valid assignment' using errcode = '42501';
end;
$$;

create or replace function public.trips_reassign_guard()
returns trigger
language plpgsql
SECURITY DEFINER
set search_path = ''
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.vehicle_id is distinct from old.vehicle_id
     or new.driver_id is distinct from old.driver_id
     or new.trip_date is distinct from old.trip_date
  then
    if new.driver_id is null or auth.uid() <> new.driver_id then
      raise exception 'trip identifiers cannot be changed' using errcode = '42501';
    end if;

    if not exists (
      select 1
      from public.vehicles v
      join public.assignments a on a.vehicle_id = v.id
      where v.id = new.vehicle_id
        and a.driver_id = new.driver_id
        and new.trip_date >= a.starts_on
        and new.trip_date <= a.ends_on
    ) then
      raise exception 'edited trip must be covered by an assignment' using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;

