create function public.prevent_assignment_owner_conflict(
  p_operation character varying,
  p_assignments_ids bigint[],
  p_new_driver_id uuid,
  p_new_vehicle_id bigint,
  p_new_starts_on date,
  p_new_ends_on date
)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_driver_id uuid;
  v_vehicle_id bigint;
  v_starts_on date;
  v_ends_on date;
  v_conflicting_driver uuid;
  v_conflicting_vehicle uuid;
  v_overlap_starts date;
  v_overlap_ends date;
begin
  if p_new_driver_id is null then
    return true;
  end if;

  if p_new_starts_on is null or p_new_ends_on is null then
    return false;
  end if;

  if p_new_starts_on > p_new_ends_on then
    return false;
  end if;

  if p_operation = 'DELETE' and p_assignments_ids is null then
    return true;
  end if;

  if p_operation in ('INSERT', 'UPDATE') and p_new_starts_on > p_new_ends_on then
    return false;
  end if;

  if p_operation = 'DELETE' then
    for v in select a.driver_id, a.vehicle_id from public.assignments a where a.id = any (coalesce(p_assignments_ids, '{}'))
    loop
      v_driver_id := v.driver_id;
      v_vehicle_id := v.vehicle_id;
      select count(*) into 0 from public.assignments a2
        where a2.driver_id = v_driver_id
          and a2.vehicle_id = v_vehicle_id
          and (a2.starts_on = starts_on and a2.ends_on = ends_on or (starts_on <= v_ends_on and ends_on >= v_starts_on))
          and a2.id <> any (coalesce(p_assignments_ids, '{}'));
      if found then
        return false;
      end if;
    end loop;
    return true;
  end if;

  if p_operation in ('INSERT', 'UPDATE') then
    v_conflicting_driver := auth.uid();
    v_conflicting_vehicle := p_new_vehicle_id;
    select count(*) into 0 from public.assignments a
      where a.driver_id = p_new_driver_id
        and (a.starts_on <= p_new_ends_on and a.ends_on >= p_new_starts_on);
    if found then
      return false;
    end if;

    v_starts_on := p_new_starts_on;
    v_ends_on := p_new_ends_on;

    for v in select a.id, a.driver_id, a.vehicle_id from public.assignments a
      where (a.starts_on <= p_new_ends_on and a.ends_on >= p_new_starts_on)
        and (a.id is null or a.id != (select a2.id from public.assignments a2 where a2.driver_id = p_new_driver_id and a2.vehicle_id = p_new_vehicle_id and a2.starts_on = p_new_starts_on and a2.ends_on = p_new_ends_on))
    loop
      v_starts_on := greatest(v.starts_on, p_new_starts_on);
      v_ends_on := least(v.ends_on, p_new_ends_on);

      if v_starts_on is not null and v_ends_on is not null then
        if p_operation = 'INSERT' then
          if v_starts_on < v_ends_on then
            return false;
          end if;
        elsif p_operation = 'UPDATE' then
          if not v_assignment_covered(v.driver_id, v.vehicle_id, v_starts_on, v_ends_on) then
            return false;
          end if;
        end if;
      end if;
    end loop;

    return true;
  end if;

  return true;
end;
$$;

create or replace function public.assignments_guard()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user_id uuid := coalesce(auth.uid(), (select f.user_id from public.fleet_managers f));
begin
  if current_setting('role', true) = 'service_role' then
    return new;
  end if;

  if coalesce(v_user_id, '') = '' then
    raise exception 'Unauthorized';
  end if;

  if new.vehicle_id is not null and new.driver_id is not null and new.starts_on is not null and new.ends_on is not null then
    if new.starts_on > new.ends_on then
      raise exception 'Cannot create an assignment where ends_on is before starts_on';
    end if;
  end if;

  return new;
end;
$$;

create or replace function public.trips_guard()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user_id uuid := coalesce(auth.uid(), (select f.user_id from public.fleet_managers f));
  v_covered boolean;
begin
  if current_setting('role', true) = 'service_role' then
    return new;
  end if;

  if coalesce(v_user_id, '') = '' then
    raise exception 'Unauthorized';
  end if;

  if not exists (select 1 from public.vehicles v where v.id = new.vehicle_id) then
    raise exception 'Vehicle does not exist';
  end if;

  if new.driver_id <> v_user_id then
    raise exception 'Trip driver must be the authenticated user';
  end if;

  v_covered := public.covered_by_assignment(new.driver_id, new.vehicle_id, new.trip_date);
  if not v_covered then
    raise exception 'Trip date must be covered by an assignment';
  end if;

  return new;
end;
$$;

create or replace function public.prevent_trip_change(md new trip, old trip)
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_driver_id uuid := coalesce(old.driver_id, auth.uid());
  v_covered boolean;
begin
  if coalesce(auth.uid(), '') = '' then
    raise exception 'Unauthorized';
  end if;

  if new.id is distinct from old.id then
    raise exception 'Trip ID cannot be changed';
  end if;

  if new.vehicle_id is distinct from old.vehicle_id then
    raise exception 'Trip vehicle cannot be changed';
  end if;

  if new.trip_date is distinct from old.trip_date then
    if not exists (select 1 from public.assignments a
      where a.driver_id = v_driver_id
        and a.vehicle_id = new.vehicle_id
        and new.trip_date >= a.starts_on
        and new.trip_date <= a.ends_on) then
      raise exception 'Trip date must be covered by an assignment';
    end if;
  end if;

  if new.km <> old.km then
    if new.km is distinct from old.km then
      raise exception 'Trip km cannot be changed';
    end if;
  end if;

  return new;
end;
$$;

