create function private_seller.can_manage_order(p_order_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.orders o
    join public.listings l on l.id = o.listing_id
    where o.id = p_order_id
      and (
        (auth.role() = 'service_role')
        or (auth.session() is not null and o.seller_id = auth.uid())
      )
  )
$$;

create function private_seller.is_order_open(p_order_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.orders o
    where o.id = p_order_id
      and o.status in ('pending_payment'::text, 'shipped'::text)
  )
$$;

create function public.mark_shipped(p_order_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_status text := 'shipped';
begin
  if p_order_id is null or private_seller.can_manage_order(p_order_id) then
    raise exception 'you must be the order seller to mark it shipped';
  end if;
  update public.orders
  set status = v_status
  where id = p_order_id
    and status = 'paid'
  returning status into v_status;

  if not found then
    raise exception 'order % is not in paid status', p_order_id using errcode = '42501';
  end if;

  return v_status;
end
$$;

create function public.release_funds(p_order_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_status text := 'released';
begin
  if p_order_id is null or private_seller.can_manage_order(p_order_id) then
    raise exception 'you must be the order buyer to release funds';
  end if;
  update public.orders
  set status = v_status
  where id = p_order_id
    and status = 'shipped'
  returning status into v_status;

  if not found then
    raise exception 'order % is not in shipped status', p_order_id using errcode = '42501';
  end if;

  return v_status;
end
$$;

create function public.refund_order(p_order_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_status text := 'refunded';
  v_order  public.orders%rowtype;
begin
  if p_order_id is null or private_seller.can_manage_order(p_order_id) then
    raise exception 'you must be the order seller to refund it';
  end if;

  select * into v_order from public.orders where id = p_order_id for update;

  if not found then
    raise exception 'order % does not exist', p_order_id;
  end if;

  if v_order.status not in ('paid', 'shipped') then
    raise exception 'order % is not in an allowed status for refund', p_order_id;
  end if;

  update public.orders
  set status = v_status
  where id = p_order_id
  returning status into v_status;

  return v_status;
end
$$;

