create or replace function public.mark_shipped(p_order_id bigint)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_seller_uuid uuid;
  v_current_state text;
  v_new_state text;
begin
  select seller_id, status
    into v_seller_uuid, v_current_state
    from public.orders
   where id = p_order_id
  for update
  skip locked;

  if not found then
    raise exception 'order % does not exist', p_order_id;
  end if;

  if auth.role() = 'service_role'
     or auth.uid() is distinct from v_seller_uuid then
    raise exception 'only the seller can mark an order as shipped';
  end if;

  if v_current_state = 'paid' then
    v_new_state := 'shipped';
  else
    raise exception 'only orders in status pending_payment can be marked as shipped';
  end if;

  update public.orders
     set status = v_new_state
   where id = p_order_id;

  return v_new_state;
end;
$$;

