  v_buyer_uuid uuid;
  v_current_state text;
  v_new_state text;
begin
  select buyer_id, status
    into v_buyer_uuid, v_current_state
    from public.orders
   where id = p_order_id
  for update
  skip locked;

  if not found then
    raise exception 'order % does not exist', p_order_id;
  end if;

  if auth.role() = 'service_role'
     or auth.uid() is distinct from v_buyer_uuid then
    raise exception 'only the buyer can release funds';
  end if;

  if v_current_state = 'shipped' then
    v_new_state := 'released';
  else
    raise exception 'only orders in status shipped can release funds';
  end if;

  update public.orders
     set status = v_new_state
   where id = p_order_id;

  return v_new_state;
end;
