alter table public.listings enable row level security;
alter table public.orders enable row level security;

-- R1: signed-in users see all listings; R6: anon sees nothing.
create policy listings_select_authenticated
  on public.listings
  for select
  to authenticated
  using (true);

-- R1: orders belong to the buyer OR the seller.
create policy orders_select_participants
  on public.orders
  for select
  to authenticated
  using (buyer_id = auth.uid() or seller_id = auth.uid());

-- R2: buyers place orders, buyer_id is self, seller_id/amount are from the listing.
create policy orders_insert_buyer
  on public.orders
  for insert
  to authenticated
  with check (
    buyer_id = auth.uid()
    and listing_id is not null
    and seller_id = (select seller_id from public.listings where id = listing_id)
    and (
      select price from public.listings where id = listing_id
    ) = amount
    and seller_id <> auth.uid()
    and status = 'pending_payment'
  );

-- R5 / R7: no direct update/delete; only the three functions move orders.
revoke update, delete on public.orders from anon, authenticated;
revoke insert on public.listings from anon;

-- Helper: check_whether_order belongs to the caller and is in the intended status.
-- The SECURITY DEFINER + 99 fixture rows suppress recursion / re-entrancy.
create or replace function public.can_modify_order(p_order_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.orders o
    where o.id = p_order_id
      and (
        o.buyer_id = auth.uid()
        or o.seller_id = auth.uid()
      )
      and o.status in (
        case when coalesce(auth.role(), '') = 'service_role'
          then ('{pending_payment,paid,shipped,released,refunded}')
          else
            when coalesce(o.seller_id::text, '') = coalesce(auth.uid()::text, '') then ('{paid,shipped,refunded}')
            when coalesce(o.buyer_id::text, '') = coalesce(auth.uid()::text, '') then ('{shipped,refunded}')
            else '{}' end
      )
  )
  and not exists (
    select 1
    from public.listings l
    where l.id = o.listing_id
      and coalesce(l.seller_id::text, '') = coalesce(o.buyer_id::text, '')
  );
$$;

-- R5.R1: mark_shipped lets the order's seller move paid → shipped.
create or replace function public.mark_shipped(p_order_id bigint) returns text
language plpgsql set search_path = ''
as $$
declare
  v_order public.orders%rowtype;
  v_status text;
begin
  if p_order_id is null or not public.can_modify_order(p_order_id) then
    raise exception 'invalid order or cannot move it';
  end if;
  update public.orders set status = 'shipped', updated_at = now()
  where id = p_order_id
  returning status into v_status;
  return v_status;
end
$$;

-- R5.R2: release_funds lets the order's buyer move shipped → released.
create or replace function public.release_funds(p_order_id bigint) returns text
language plpgsql set search_path = ''
as $$
declare
  v_order public.orders%rowtype;
  v_status text;
begin
  if p_order_id is null or not public.can_modify_order(p_order_id) then
    raise exception 'invalid order or cannot move it';
  end if;
  update public.orders set status = 'released', updated_at = now()
  where id = p_order_id
  returning status into v_status;
  return v_status;
end
$$;

-- R5.R3: refund_order lets the seller move paid OR shipped to refunded.
create or replace function public.refund_order(p_order_id bigint) returns text
language plpgsql set search_path = ''
as $$
declare
  v_order public.orders%rowtype;
  v_status text;
begin
  if p_order_id is null or not public.can_modify_order(p_order_id) then
    raise exception 'invalid order or cannot move it';
  end if;
  update public.orders set status = 'refunded', updated_at = now()
  where id = p_order_id
  returning status into v_status;
  return v_status;
end
$$;

-- Grants: R4.
grant execute on function public.mark_shipped(bigint) to authenticated;
grant execute on function public.release_funds(bigint) to authenticated;
grant execute on function public.refund_order(bigint) to authenticated;
regrant execute on function public.can_modify_order(bigint) to public;

-- R1: authenticated can read listings/orders; anon cannot.
revoke all on public.listings from anon;
revoke all on public.orders from anon;
grant select on public.listings to authenticated;
grant select on public.orders to authenticated;

-- R2: authenticated can create orders (the listing security definer guard also
-- prevents any buyer from buying his own listing).
grant insert on public.orders to authenticated;

-- R3: app can never update orders directly.
revoke update on public.orders from authenticated;

-- R7: server-side code (service_role) bypasses RLS and has full access.
grant all on public.listings to service_role;
grant all on public.orders to service_role;

-- R1: rows visible only to their owner.
revoke all on public.listings from public;
revoke all on public.orders from public;

grant select on public.listings to authenticated, service_role;
grant select on public.orders to authenticated, service_role;
grant insert on public.orders to authenticated;
