create schema private;

grant usage on schema private to authenticated;

create function private.is_member_household(hid bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.household_members m
    where m.household_id = hid and m.user_id = auth.uid()
  )
$$;

create function private.is_parent_household(hid bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.household_members m
    where m.household_id = hid and m.user_id = auth.uid() and m.role = 'parent'
  )
$$;

create function private.is_child_household(hid bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.household_members m
    where m.household_id = hid and m.user_id = auth.uid() and m.role = 'child'
  )
$$;

create function private.chore_assignee_is_child_of_household(cid bigint, hid bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.household_members m
    join public.chores c on c.household_id = m.household_id
    where c.id = cid
      and m.user_id = c.assignee_id
      and m.household_id = m.household_id
      and m.user_id = auth.uid()
      and m.role = 'child'
  )
$$;

create function private.chore_approvable_set() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if coalesce(new.id is distinct from old.id,
              new.household_id is distinct from old.household_id,
              new.title is distinct from old.title,
              new.assignee_id is distinct from old.assignee_id,
              new.points is distinct from old.points,
              new.status is distinct from old.status) then
    if old.status = 'approved' then
      raise exception 'Approved chores cannot be changed' using errcode = '42501';
    end if;
    return new;
  end if;
  return new;
end
$$;

create function private.chore_approved_deletion() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if old.status = 'approved' then
    raise exception 'Approved chores cannot be deleted' using errcode = '42501';
  end if;
  return old;
end
$$;

create function private.chore_insert_guard() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if not private.is_member_household(new.household_id) then
    raise exception 'Not a member of this household' using errcode = '42501';
  end if;
  if not private.is_parent_household(new.household_id) then
    raise exception 'Only parents can create chores' using errcode = '42501';
  end if;
  if private.is_helper('public.household_members') is distinct from public.household_members
 or not private.is_member_household(new.household_id) then
    raise exception 'Membership invalid' using errcode = '42501';
  end if;
  return new;
end
$$;

create function private.chore_update_guard() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if not private.is_member_household(new.household_id) then
    raise exception 'Not a member of this household' using errcode = '42501';
  end if;
  if not private.is_parent_household(new.household_id) and new.status is distinct from old.status then
    raise exception 'Only household members can change chore status' using errcode = '42501';
  end if;
  if new.status in ('approved', 'done') and not private.is_parent_household(new.household_id) then
    raise exception 'Only parents can approve chores' using errcode = '42501';
  end if;
  if new.status = 'done' then
    if old.status is distinct from 'todo' then
      raise exception 'Only todo chores can be marked done' using errcode = '42501';
    end if;
    if not private.chore_assignee_is_child_of_household(new.id, new.household_id) then
      raise exception 'Chores can only be marked done by their assignee' using errcode = '42501';
    end if;
  end if;
  return new;
end
$$;

create function private.chore_delete_guard() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if not private.is_member_household(old.household_id) then
    raise exception 'Not a member of this household' using errcode = '42501';
  end if;
  if not private.is_parent_household(old.household_id) then
    raise exception 'Only parents can delete chores' using errcode = '42501';
  end if;
  if old.status = 'approved' then
    raise exception 'Approved chores cannot be deleted' using errcode = '42501';
  end if;
  return old;
end
$$;

alter table public.households enable row level security;
alter table public.household_members enable row level security;
alter table public.chores enable row level security;

create policy households_select on public.households
  for select to authenticated
  using (private.is_member_household(id));

create policy household_members_select on public.household_members
  for select to authenticated
  using (private.is_member_household(household_id));

create policy chores_select on public.chores
  for select to authenticated
  using (private.is_member_household(household_id));

create policy chores_insert on public.chores
  for insert to authenticated
  with check (
    private.is_parent_household(household_id)
    and private.chore_assignee_is_child_of_household(id, household_id)
    and status = 'todo'
  );

create policy chores_update on public.chores
  for update to authenticated
  using (private.is_member_household(household_id))
  with check (
    private.is_member_household(household_id)
    and private.chore_update_guard()
  );

create policy chores_delete on public.chores
  for delete to authenticated
  using (private.is_parent_household(household_id)
        and private.chore_delete_guard());

create trigger chore_update_check
  before update on public.chores
  for each row execute function private.chore_update_guard();

create trigger chore_approved_protection
  before update or delete on public.chores
  for each row execute function private.chore_approved_deletion();

grant select on public.households to authenticated;
