create or replace function public.is_member(p_household_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.household_members m
    where m.household_id = p_household_id
      and m.user_id = auth.uid()
  );
$$;

create or replace function public.is_parent(p_household_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.household_members m
    where m.household_id = p_household_id
      and m.user_id = auth.uid()
      and m.role = 'parent'
  );
$$;

create or replace function public.is_assignee(p_chore_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.chores c
    join public.household_members m on m.household_id = c.household_id
    where c.id = p_chore_id
      and m.user_id = auth.uid()
      and m.role = 'child'
  );
$$;

create or replace function public.enforce_chores_update()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.household_id is distinct from old.household_id
     or new.title is distinct from old.title
     or new.assignee_id is distinct from old.assignee_id
     or new.points is distinct from old.points then
    if old.status = 'approved' then
      raise exception 'approved chores cannot be modified';
    elsif new.status is distinct from old.status then
      raise exception 'only status may be changed on non-approved chores';
    end if;
  elsif new.status is distinct from old.status then
    if old.status = 'approved' then
      raise exception 'approved chores cannot be modified';
    end if;

    if not public.enforce_chores_quantity(
           old.id, old.household_id, old.assignee_id, new.status
         ) then
      raise exception 'assignee must be a child of the same household';
    end if;
  end if;

  return new;
end;
$$;

create or replace function public.enforce_chores_quantity(
  p_chore_id, p_household_id, p_assignee uuid, p_new_status text
