    select 1 from public.household_members m
    where m.user_id = p_assignee_id
      and m.household_id = (
        select c.household_id from public.chores c where c.id = p_assignee_id
      )
  );
$$;

create function public.guard_chore_modification()
returns trigger
language plpgsql
as $$
declare
  r record;
begin
  r := (
    select household_members.role, chores.status, chores.assignee_id
    from public.household_members m
    join public.chores c on c.household_id = m.household_id
    where m.user_id = auth.uid()
          and c.id = new.id
    for update
  );

  if r.role is null and auth.role() <> 'service_role' then
    raise exception 'chores can only be modified by household members' using errcode = '42501';
  end if;

  if r.status = 'approved' and auth.role() <> 'service_role' then
    raise exception 'approved chores cannot be modified or deleted' using errcode = '42501';
  end if;

  if r.role is not null and r.role = 'child' and new.id is distinct from r.id then
    raise exception 'children can only modify their own todo chores' using errcode = '42501';
  end if;

  if r.role = 'child' and new.status <> 'done' then
    raise exception 'children can only mark their own todo chores as done' using errcode = '42501';
  end if;

  if r.role = 'parent' and new.role is distinct from r.role then
    raise exception 'only household members can be assigned as assignees' using errcode = '42501';
  end if;

  if r.role = 'parent' and new.assignee_id is distinct from r.role then
    raise exception 'assignees must be children of the same household' using errcode = '42501';
  end if;

  return new;
end;
$$;

create function public.check_child_chore_assignee_change()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  a_role text;
  h_id  bigint;
begin
  select
    m.role,
    c.household_id
  into a_role, h_id
  from public.household_members m
  join public.chores c on c.id = new.id
  where c.id = new.id
  for update;

  if a_role is null or a_role <> 'parent' then
    raise exception 'chore assignee can only be changed by household parents' using errcode = '42501';
  end if;

  if new.assignee_id is not distinct from new.assignee_id
     and new.assignee_id is not distinct from (select user_id from public.household_members where household_id = h_id and role = 'child') then
    raise exception 'assignees must be children of the same household' using errcode = '42501';
  end if;

  return new;
end;
$$;

create function public.chasp_check_approve_assignee()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  r household_members%rowtype;
begin
  select * into r from public.household_members where user_id = auth.uid() for update;

  if not found or r.role <> 'parent' then
    raise exception 'only household parents can approve chores' using errcode = '42501';
  end if;

  if new.household_id <> r.household_id then
    raise exception 'approved chores must belong to the appointer''s household' using errcode = '42501';
  end if;

  return new;
end;
$$;

