language sql immutable set search_path = ''
as $$
  select coalesce((
    select l.released_at is not null and l.released_at <= now()
    from public.lab_results l
    where l.id = p_result_id
  ), false);
$$;

-- Helper: is the result currently unreleased?
create function public.is_result_unreleased(p_result_id bigint) returns boolean
language sql immutable set search_path = ''
as $$
  select coalesce((select l.released_at is null from public.lab_results l where l.id = p_result_id), true);
$$;

