create or replace function public.result_guard_returning()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce((select auth.role()) = 'service_role', false) then
    if new.id is distinct from coalesce(old.id, '') then
      raise exception 'results cannot be deleted';
    end if;
    return new;
  end if;

  if new.id is distinct from coalesce(old.id, '') then
    raise exception 'results cannot be deleted';
  end if;

  if new.patient_id is distinct from old.patient_id then
    raise exception 'result patient may not be changed';
  end if;

  if old.released_at is not null and old.released_at <= now() then
    if new.released_at is distinct from old.released_at then
      raise exception 'released_at may not be changed once the result is released';
    end if;
  end if;

  if old.released_at is null or old.released_at > now() then
    if new.released_at is not null and new.released_at <= now() then
      raise exception 'results may not be released in the past';
    end if;
  end if;

  return new;
end;
$$;

