create or replace function public.is_tenant_admin(t text)
returns boolean
language sql
immutable
stable
security definer
set search_path = public, pg_temp
as $$
  select auth.role() = 'authenticated'
     and auth.jwt() -> 'app_metadata' ->> 'tenant_id' = t
     and auth.jwt() -> 'app_metadata' ->> 'role' = 'admin'
$$;

create or replace function public.item_share_grant(target_tenant text, expires_at timestamptz)
returns boolean
language plpgsql
security invoker
set search_path = public, pg_temp, auth
as $$
declare
  this_tenant text := auth.jwt() -> 'app_metadata' ->> 'tenant_id';
begin
  if this_tenant is null then
    return false;
  end if;

  if coalesce(auth.role(), '') = 'service_role' then
    return true;
  end if;

  if not public.is_tenant_tenant_of(this_tenant) then
    return false;
  end if;

  if public.is_tenant_admin(this_tenant) then
    return true;
  end if;

  if target_tenant <> this_tenant then
    return false;
  end if;

  if expires_at is not null and expires_at < now() then
    return false;
  end if;

  return true;
end;
$$;

