create or replace function public.checkins_guard_requester_role()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if auth.role() is not null and auth.role() = 'authenticated' then
    if tg_op = 'INSERT' then
      if new.checked_in_at is distinct from now() then
        raise exception 'checked_in_at cannot be set by the app'
