      end if;

      if new.user_id is distinct from auth.uid() then
        raise exception 'checkins can only be created for the querying user'
          using errcode = '42501';
      end if;

      if not public.is_event_live(new.event_id) then
        raise exception 'checkins are only allowed while the event is live'
          using errcode = '42501';
      end if;

      if exists (select 1 from public.checkins c where c.event_id = new.event_id and c.user_id = new.user_id) then
        raise exception 'user is already checked in to this event'
          using errcode = '42501';
      end if;

      return new;
    else
      raise exception 'only insert is permitted on checkins'
        using errcode = '42000';
    end if;
  end if;

  raise exception 'only signed-in users and server-side roles are permitted'
    using errcode = '42501';
end;
$$;

