      select 1
      from public.events e
      where e.id = checkins.event_id
        and now() >= e.starts_at
        and now() <= e.ends_at
    )
  );

-- R3 and R4: no update/delete policies for authenticated, and no policies at all for anon
-- checked_in_at is enforced by the default column value and a defensive trigger/privileges combo
