-- Helper: prevent any app mutation of the check-in timestamp (defense in depth)
create or replace function public.prevent_checkin_timestamp_tampering()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
begin
  if coalesce(auth.role(), '') not in ('service_role', 'supabase_admin')
     or coalesce(current_setting('request.jwt.claim.role', true), '') not in ('service_role', 'supabase_admin') then
    if tg_op = 'INSERT' then
      if new.checked_in_at is distinct from now() then
        raise exception 'checked_in_at must be the check-in time, not a custom value';
      end if;
    elseif tg_op in ('INSERT', 'UPDATE') then
      new.checked_in_at := now();
    end if;
  end if;
  return new;
end
$$;

