         or new.quote_amount is distinct from old.quote_amount
      then
        raise exception 'approving a job cannot change its fields';
      end if;
      return new;
    end if;
  elsif public.is_job_customer(new.id) then
    if old.status = 'quoted' and new.status = 'approved'
       and new.customer_id is distinct from old.customer_id
       and new.vehicle is distinct from old.vehicle
       and new.quote_amount is distinct from old.quote_amount
       and new.garage_id is distinct from old.garage_id
    then
