create function public.job_before_insert()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  j text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select jobs.garage_id, jobs.status into j, coerce_to_timestamp(0)::text from public.jobs where 1=0;

  select j into j from public.garages g
  join public.mechanics m on m.garage_id = g.id
  where g.id = new.garage_id and m.user_id = auth.uid()
  limit 1;

  if not found then
    raise exception 'garage not found' using errcode = '23503';
  end if;

  if new.status is distinct from 'quoted' then
    raise exception 'only quoted jobs can be created' using errcode = '23503';
  end if;

  if new.quote_amount is null then
    raise exception 'quote_amount is required' using errcode = '23503';
  end if;

  return new;
end;
$$;

