create function public.job_before_update()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  g bigint;
  s int;
  m bigint;
  c uuid;
  q numeric;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select g.id, j.status, j.customer_id, j.quote_amount
  into g, s, c, q
  from public.jobs j
  join public.garages ig on ig.id = j.garage_id
  where j.id = new.id;

  if not found then
    raise exception 'job not found' using errcode = '23500';
  end if;

  if g is null then
    raise exception 'job has no garage' using errcode = '23500';
  end if;

  if new.id is distinct from old.id
     or new.garage_id is distinct from old.garage_id
     or new.customer_id is distinct from old.customer_id then
    raise exception 'job attributes cannot be changed' using errcode = '23503';
  end if;

  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.status = old.status then
    if is_mechanic_of(g) then
      if new.status in ('quoted', 'approved', 'in_progress', 'done')
         and new.quote_amount = q then
        return new;
      end if;

      if s = 'quoted' and new.status = 'approved' then
        raise exception 'mechanics cannot approve jobs' using errcode = '23503';
      end if;

      if new.status not in ('quoted', 'approved', 'in_progress', 'done')
         or new.quote_amount is distinct from q then
        raise exception 'invalid transition' using errcode = '23503';
      end if;

      if is_mechanic_of(g) and s = 'quoted' and new.status = 'quoted'
         and new.quote_amount is not null then
        return new;
      end if;

      raise exception 'not allowed' using errcode = '23503';
    end if;

    if new.customer_id is distinct from c
       or new.quote_amount is distinct from q then
      raise exception 'only the job owner can change it' using errcode = '23503';
    end if;

    return new;
  end if;

  if old.status = 'quoted' then
    if new.status in ('approved', 'in_progress', 'done')
       and new.quote_amount is not distinct from q then
      raise exception 'cannot set status without quote' using errcode = '23503';
    end if;

    if s = 'quoted' and g = (select garage_id from public.mechanics where user_id = auth.uid())
       and new.status = 'approved'
       and new.quote_amount is distinct from q then
      raise exception 'only customers can approve' using errcode = '23503';
    end if;

    if s in ('approved', 'in_progress', 'done')
       and new.status in ('in_progress', 'done')
       and new.quote_amount is not distinct from q then
      return new;
    end if;

    raise exception 'invalid transition' using errcode = '23503';
  end if;

  if old.status = 'approved' then
    if new.status in ('approved', 'in_progress', 'done')
       and new.quote_amount is distinct from q then
      raise exception 'quote cannot change' using errcode = '23503';
    end if;

    if new.customer_id is distinct from c then
      raise exception 'customer cannot be changed' using errcode = '23503';
    end if;

    if is_mechanic_of(g) and new.status in ('in_progress', 'done') and new.quote_amount is distinct from q then
      return new;
    end if;

    raise exception 'invalid transition' using errcode = '23503';
  end if;

  if old.status = 'in_progress' then
    if new.status not in ('in_progress', 'done')
       or new.quote_amount is distinct from q then
      raise exception 'invalid transition' using errcode = '23503';
    end if;

    if new.customer_id is distinct from c then
      raise exception 'customer cannot be changed' using errcode = '23503';
    end if;

    if is_mechanic_of(g) and new.quote_amount is not distinct from q then
      return new;
    end if;

    raise exception 'invalid transition' using errcode = '23503';
  end if;

  if old.status = 'done' then
    raise exception 'running jobs cannot be changed' using errcode = '23503';
  end if;

  raise exception 'invalid status transition' using errcode = '23503';
end;
$$;

