create or replace function jobs_guard(p_operation text, p_id bigint, p_new row, p_old row)
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_garage bigint;
  v_customer uuid := auth.uid();
  v_role text := auth.role();
begin
  if v_role = 'service_role' or p_old is null then
    if p_operation = 'INSERT' then
      v_garage := (select j.garage_id from public.jobs j where j.id = new.id);
      if v_garage is null then
        raise exception 'Job is not in public.garages';
      end if;
      if not is_garage_mechanic(v_garage) then
        raise exception 'Only mechanics of a garage may open jobs for it';
      end if;
    end if;
    return new;
  end if;

  if p_operation = 'DELETE' then
    raise exception 'Jobs are never deleted';
  end if;

  if p_operation = 'INSERT' then
    v_garage := new.garage_id;
    if not is_garage_mechanic(v_garage) then
      raise exception 'Only mechanics of a garage may open jobs for it';
    end if;
    if new.customer_id <> v_customer then
      raise exception 'Jobs cannot be opened by non-customers';
    end if;
    if new.status <> 'quoted' then
      raise exception 'Jobs must be opened with status quoted';
    end if;
    return new;
  end if;

  if p_operation = 'UPDATE' then
    if p_old is null then
      raise exception 'Old row not available';
    end if;

    v_garage := p_old.garage_id;
    if not is_garage_mechanic(v_garage) then
      raise exception 'Jobs can only be changed by mechanics of their garage';
    end if;

    if public.is_customer_of_job(p_id) then
      if p_new is distinct from p_old then
        raise exception 'Only the customer may change their job and only the status is allowed';
      end if;
      if p_new.status <> 'approved' then
        raise exception 'Customers may only approve a quoted job';
      end if;
      if p_new.quote_amount is distinct from p_old.quote_amount then
        raise exception 'Approving cannot change the quote amount';
      end if;
      return new;
    end if;

    if p_new.status not in ('in_progress', 'done') then
      raise exception 'Only in_progress and done transitions are allowed for mechanics';
    end if;

    if p_new.quote_amount is distinct from p_old.quote_amount then
      raise exception 'Quote amount may not be changed after opening';
    end if;

    if p_new.customer_id is distinct from p_old.customer_id then
      raise exception 'Customers may not be changed';
    end if;

    return new;
  end if;

  raise exception 'Unsupported operation: %', p_operation;
end;
$$;

