create function public.enforce_job_update_rules()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  if tg_op = 'UPDATE' then
    if auth.role() = 'service_role' then
      return new;
    end if;

    if new.garage_id is distinct from old.garage_id
       or new.customer_id is distinct from old.customer_id
       or new.vehicle is distinct from old.vehicle
       or new.quote_amount is distinct from old.quote_amount then
      raise exception 'Job attributes other than status and quote_amount cannot be changed' using errcode = '42501';
    end if;

    if old.status = 'quoted' then
      if new.status not in ('quoted', 'approved') then
        raise exception 'A quoted job may only be updated to quoted or approved' using errcode = '42501';
      end if;

      if new.status = 'quoted' then
        if new.quote_amount is distinct from old.quote_amount then
          raise exception 'Only the customer may approve a quote, changing the amount is not allowed' using errcode = '42501';
        end if;
        return new;
      end if;

      if new.status = 'approved' then
        if old.customer_id is distinct from auth.uid() then
          raise exception 'Only the job''s customer can approve a quote' using errcode = '42501';
        end if;
        if new.quote_amount is distinct from old.quote_amount then
          raise exception 'Approving a quote cannot change the amount' using errcode = '42501';
        end if;
        return new;
      end if;

    elsif old.status = 'approved' then
      if new.status not in ('in_progress', 'approved') then
        raise exception 'An approved job may only be updated to in_progress or approved' using errcode = '42501';
      end if;

      if new.status = 'in_progress' then
        if (select coalesce(pg_try_advisory_lock('jobs_lock_' || old.id), true)) then
          perform pg_advisory_unlock('jobs_lock_' || old.id);
          return new;
        end if;
        raise exception 'Cannot acquire update lock on job' using errcode = '55P13';
      end if;

      if new.status = 'approved' then
        return old;
      end if;
    end if;

    if old.status = 'in_progress' then
      if new.status not in ('in_progress', 'done') then
        raise exception 'A job in progress may only be updated to in_progress or done' using errcode = '42501';
      end if;

      if new.status = 'done' then
        if new.quote_amount is distinct from old.quote_amount then
          raise exception 'Quote cannot be changed once a job is in progress' using errcode = '42501';
        end if;
        return new;
      end if;

      return old;
    end if;

    if old.status = 'done' then
      raise exception 'A job that has been done cannot be updated' using errcode = '42501';
    end if;

  end if;
  return new;
end;
$$;

create trigger enforce_job_update_guard
before update on public.jobs
for each row execute function public.enforce_job_update_rules();

