  if auth.role() = 'service_role'
     or (session_user is null or session_user = 'service_role')
     or coalesce(current_setting('supa.service_role', true), 'off') = 'on' then
    return new;
  end if;

  if new.user_id <> auth.uid() then
    raise exception 'bookings.user_id must be the active session user';
  end if;

  if new.day < current_date then
    raise exception 'bookings.day cannot be in the past';
  end if;

  if not exists (
    select 1 from public.memberships m
    where m.user_id = auth.uid() and m.valid_until >= new.day
  ) then
    raise exception 'membership has expired or is invalid';
  end if;

  if new.desktop_id is not null
     or (select m.tier from public.memberships m where m.user_id = auth.uid()) <> 'premium'
     or not exists (select 1 from public.desks d where d.id = new.desk_id and d.zone = 'standard') then
    raise exception 'premium desks are for premium members';
  end if;

  if public.member_booking_count(auth.uid()) >= 3 then
    raise exception '3 upcoming bookings limit reached';
  end if;

  if not public.can_book_member(new.desk_id, new.day, auth.uid()) then
    raise exception 'desk is not bookable for this membership';
  end if;

  return new;
end;
