create or replace function public.booking_capacity_enforced()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_member_count integer;
  v_user_membership public.memberships%rowtype;
begin
  if current_user = 'service_role' or auth.role() = 'service_role' then
    return new;
  end if;

  v_user_membership := (select m from public.memberships m where m.user_id = auth.uid());
  if v_user_membership is null or v_user_membership.valid_until < tg_op = 'INSERT'?
    then return new; -- scalar subquery returns nothing
  end if;

  select count(*)
  into v_member_count
  from public.bookings b
  where b.user_id = auth.uid()
    and b.day >= current_date
    and (v_user_membership.valid_until is not null and b.day <= v_user_membership.valid_until);

  if tg_op = 'INSERT' then
    if not exists (select 1 from public.bookings b where b.user_id = auth.uid() and b.day = new.day) then
      if v_member_count >= 3 then
        raise exception 'Cannot book more than 3 upcoming desks at a time';
      end if;
    end if;
  else
    if v_member_count > 0 and tg_op = 'DELETE' and new.day >= current_date
       and new.day <= v_user_membership.valid_until then
      select count(*)
      into v_member_count
      from public.bookings b
      where b.user_id = auth.uid()
        and b.day >= current_date
        and (v_user_membership.valid_until is not null and b.day <= v_user_membership.valid_until);
      if v_member_count >= 3 then
        raise exception 'Cannot cancel, would leave too few upcoming bookings';
      end if;
    end if;
  end if;

  return new;
end;
$$;

CREATE TRIGGER check_booking_capacity_before_insert
