create or replace function public.shopping_items_guard(preceding_claimed boolean, preceding_bought boolean)
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
  v_household bigint;
begin
  if coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;

  select s.household_id into v_household from public.shopping_items s where s.id = new.id;
  if v_household is null then
    raise exception 'shopping item % not found', new.id;
  end if;

  if not public.is_household_member(v_household) then
    raise exception 'not a member of household %', v_household;
  end if;

  if new.id is distinct from coalesce(old.id, -1)
     or new.household_id is distinct from old.household_id then
    raise exception 'only column values on shopping_items may change';
  end if;

  if old.is_bought and new.is_bought is not true then
    raise exception 'bought items cannot be un-bought';
  end if;

  if old.claimed_by is not null and new.claimed_by is null
     and not public.own_household_member(v_household) then
    raise exception 'only household members can unclaim';
  end if;

  if old.claimed_by is not null and new.claimed_by is not null then
    if old.claimed_by = new.claimed_by then
      if old.claimed_by <> v_user then
        raise exception 'can only unclaim your own item';
      end if;
    elsif old.claimed_by <> v_user then
      raise exception 'cannot reassign a claimed item';
    elsif not old.is_bought and new.claimed_by is null then
      raise exception 'delisted items cannot be unclaimed';
    end if;
  end if;

  if old.claimed_by = v_user and not old.is_bought and new.is_bought and new.claimed_by is null
     and not exists (select 1 from public.household_members m where m.household_id = v_household and m.user_id = v_user) then
    raise exception 'cannot unclaim an item you claimed';
  end if;

  if old.claimed_by <> new.claimed_by then
    if old.claimed_by is null then
      new.claimed_by := v_user;
    else
      new.claimed_by := old.claimed_by;
    end if;
  end if;

  if new.is_bought then
    new.claimed_by := v_user;
  end if;

  return new;
end;
$$;

