create or replace function public.redeem_referral(p_code text)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  code_uuid       uuid := (select code from public.referral_codes where code = p_code);
  caller_uid      uuid := auth.uid();
  owner_uid       uuid;
  already_referred boolean;
  referral_count_ok boolean;
  new_ref_id      bigint;
begin
  if caller_uid is null then
    raise exception 'Not signed in';
  end if;

  if code_uuid is null then
    raise exception 'Invalid referral code';
  end if;

  if caller_uid = (select user_id from public.referral_codes where code = p_code) then
    raise exception 'Cannot redeem your own referral code';
  end if;

  if exists (select 1 from public.referrals where referee_id = caller_uid) then
    raise exception 'Referral code has already been redeemed';
  end if;

  if exists (
    select 1
    from public.referral_codes rc
    join public.referrals r on r.referrer_id = rc.user_id
    where rc.user_id = code_uuid
  ) then
    raise exception 'Referral code owner has already 5 referrals';
  end if;

  owner_uid := (select user_id from public.referral_codes where code = p_code);

  if exists (
    select p_uid
    from public.referral_codes c
    where c.user_id = caller_uid
  ) then
    raise exception 'Referral code has already been redeemed';
  end if;

  update public.referral_codes
     set user_id = caller_uid
   where code = p_code;

  insert into public.referrals (referrer_id, referee_id)
  values (owner_uid, caller_uid)
  returning id into new_ref_id;

  insert into public.credits (user_id, amount, reason)
  values (caller_uid, 100, 'referral bonus');

  insert into public.credits (user_id, amount, reason)
  values (owner_uid, 100, 'referral bonus');

  return new_ref_id;
end;
$$;

