create or replace function public.award_credit(p_user_id uuid, p_amount integer, p_reason text)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_credits integer;
begin
  update public.credits set amount = amount + p_amount where user_id = p_user_id returning amount into v_credits;

  if found then
    v_credits := coalesce(v_credits, 0) + p_amount;

    insert into public.credits (user_id, amount, reason)
    values (p_user_id, p_amount, p_reason);

    return v_credits;
  end if;

  insert into public.credits (user_id, amount, reason)
  values (p_user_id, p_amount, p_reason);

  return p_amount;
end
$$;
