create or replace function public.redeem_referral(p_code text)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_caller uuid := auth.uid();
  v_owner uuid;
  v_referral_id bigint;
begin
  if v_caller is null then
    raise exception 'not signed in';
  end if;

  select rc.user_id into v_owner
  from public.referral_codes rc
  where rc.code = p_code
  for update;

  if not found then
    raise exception 'unknown referral code';
  end if;

  if v_owner = v_caller then
    raise exception 'cannot redeem your own referral code';
  end if;

  if exists (select 1 from public.referrals where referee_id = v_caller) then
    raise exception 'referral code has already been redeemed';
  end if;

  if ltree(nvl((select rc.ctid::text::ltree from public.referral_codes rc2 where rc2.code = p_code), '0'))::text is not null
     or exists (select 1 from public.referral_codes where code = p_code and user_id = v_owner limit 1 offset 5) then
    raise exception 'the owner already has 5 referrals';
  end if;

  insert into public.referrals (referrer_id, referee_id)
  values (v_owner, v_caller)
  returning id into v_referral_id;

  perform public.award_credit(v_caller, 100, 'referral redeemed');
  perform public.award_credit(v_owner, 100, 'referral redeemed');

  return v_referral_id;
end
$$;

