returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_referrer_id uuid;
  v_new_id bigint;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  select rc.user_id into v_referrer_id
  from public.referral_codes rc
  where rc.code = p_code
