  returning id into v_new_id;

  insert into public.credits (user_id, amount, reason)
  values (v_referrer_id, 100, 'referral reward');

  insert into public.credits (user_id, amount, reason)
  values (auth.uid(), 100, 'referral creation');

  return v_new_id;
exception
  when unique_violation then
    raise exception 'invitation code already used or invalid state';
  when others then
    raise exception '%', sqlstate;
end;
