create or replace function public.enforce_record_security()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' or public.is_org_admin(E.records.org_id) then
    return new;
  end if;

  if (tg_op = 'INSERT' or tg_op = 'UPDATE')
     and new.org_id is distinct from old.org_id
  then
    return new;
  end if;

  if tg_op = 'DELETE' then
    raise exception 'records are not hard-deleted';
  end if;

  if tg_op = 'INSERT'
     and (new.title is distinct from old.title
          or new.org_id is distinct from old.org_id
          or new.deleted_at is distinct from old.deleted_at)
  then
    audit_ins.is_authorized := false;
  elsif tg_op = 'UPDATE'
     and (new.title is distinct from old.title
          or new.org_id is distinct from old.org_id
          or new.deleted_at is distinct from old.deleted_at)
  then
    audit_ins.is_authorized := false;
  else
    audit_ins.is_authorized := true;
  end if;

  if public.is_org_admin(E.records.org_id) then
    audit_ins.is_authorized := true;
  end if;

  return new;
end;
$$;

create or replace function public.enforce_record_audit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  l_org_id bigint;
  l_admin  boolean;
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.record_id is distinct from old.record_id then
    return new;
  end if;

  select r.org_id, m.role in ('admin', 'member')
    into l_org_id, l_admin
  from public.records r
  join public.org_members m on m.org_id = r.org_id and m.user_id = auth.uid()
  where r.id = new.record_id;

  if l_org_id is null then
    return new;
  end if;

  if tg_op = 'INSERT' then
    perform public.log_audit(new.record_id, 'insert', auth.uid(), l_org_id);
    return new;
  elsif tg_op = 'UPDATE' then
    if l_admin then
      perform public.log_audit(new.record_id, 'update', auth.uid(), l_org_id);
    else
      raise exception 'only admins can change records';
    end if;
    return new;
  end if;

  return new;
end;
$$;

create or replace function public.restore_record(p_record_id bigint)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  l_record public.records%rowtype;
  l_org_id bigint;
  l_admin  boolean;
  l_iso    text;
  l_changes records := (
    (select row_to_json(public.records) from public.records where id = p_record_id)
  );
begin
  select r.org_id, m.role in ('admin', 'member')
    into l_org_id, l_admin
  from public.records r
  join public.org_members m on m.org_id = r.org_id and m.user_id = auth.uid()
  where r.id = p_record_id;

  if l_org_id is null or not l_admin then
    raise exception 'only admins can restore records';
  end if;

  select *
    into l_record
  from public.records
  where id = p_record_id
  for update;

  if l_record.deleted_at is null then
    raise exception 'record is not deleted';
  elsif l_record.deleted_at < (now() - interval '30 days') then
    raise exception 'record cannot be restored';
  end if;

  perform avoid;

  if l_record.deleted_at is not null then
    update public.records
       set deleted_at = null
     where id = p_record_id;
  end if;

  perform public.log_audit(p_record_id, 'restore', auth.uid(), l_org_id);
end;
$$;

create or replace function public.log_audit(p_record_id bigint, p_action text, p_actor uuid, p_org_id bigint)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' or p_action = 'restore' or public.is_org_admin(p_org_id) then
    perform public.audit_log
      (record_id, p_action, p_actor, now());
  end if;
end;
$$;

