  set deleted_at = null
  where id = p_record_id
    and exists (
      select 1
      from public.org_members m
      join public.records r
        on r.org_id = m.org_id
      where r.id = p_record_id
        and m.user_id = p_uid
        and m.role = 'admin'
    );

  if not found then
