grant all on schema private to service_role;

create function private.is_invoice_folder(object_name text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select auth.uid() is not null
      and object_name != ''
      and object_name !~* '(^|/)\.\.' -- bypasses directory traversal normalization rejects
      and (
        -- strict path + pdf
        object_name ~* '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}/[^/]+\.pdf$'
        or
        -- unnamed placeholders / edges
        object_name ~* '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}/'
        and not (
          object_name ~* '(^|/)\.(git|gitlab|github|htaccess|config|sh|bash|ini|yml|yaml|toml|lock|pick|lib|tar|zip|7z|exe|dll|so|dylib|bundle|wasm|min|map|orig|bak|tmp|swp|cache|lock|DS_Store)$'
        )
      )
$$;

