create function public.break_glass_grant_expires(p_patient_id bigint)
returns timestamptz
language sql
stable
security definer
set search_path = ''
as $$
  select expires_at from public.break_glass_grants
  where patient_id = p_patient_id
    and clinician_id = auth.uid()
    and expires_at > now() limit 1
$$;

create function public.break_glass(p_patient_id bigint, p_reason text)
returns timestamptz
language plpgsql
security definer
set search_path = 'public'
as $$
declare
  v_clinician uuid := auth.uid();
  v_time     timestamptz;
begin
  if not exists (select 1 from public.clinicians where user_id = v_clinician) then
    raise exception 'caller is not a clinician', detail = 'not in public.clinicians';
  end if;
  if exists (select 1 from public.patients where id = p_patient_id) = false then
    raise exception 'unknown patient', detail = 'patient_id ' || p_patient_id || ' does not exist';
  end if;
  if length(trim(p_reason)) < 10 then
    raise exception 'reason must be at least 10 characters', detail = 'trimmed length ' || length(trim(p_reason));
  end if;

  updated := 0;
  perform pg_advisory_xact_lock(p_patient_id);

  select count(*)::integer into updated
  from public.break_glass_grants
  where patient_id = p_patient_id
    and clinician_id = v_clinician;

  if updated > 0 then
    update public.break_glass_grants
    set expires_at = now() + interval '1 hour'
    where patient_id = p_patient_id
      and clinician_id = v_clinician;
  else
    insert into public.break_glass_grants (patient_id, clinician_id, reason, expires_at)
    values (p_patient_id, v_clinician, p_reason, now() + interval '1 hour')
    returning expires_at into v_time;
  end if;

  return v_time;
end
$$;

