language plpgsql security definer set search_path = ''
as $$
declare
  v_from bigint;
  v_current integer;
  v_to_warehouse bigint := p_to;
  v_dst_exists boolean;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if p_from = p_to then
    raise exception 'source and destination are the same' using errcode = '23514';
  end if;

  if p_qty is null or p_qty <= 0 then
    raise exception 'quantity must be positive' using errcode = '22003';
  end if;

  select warehouse_id into v_from
  from public.warehouses
  where id = p_from;

  if v_from is null then
    raise exception 'source warehouse % does not exist', p_from using errcode = '23503';
  end if;

  if not private.is_warehouse_staff(v_from) then
    raise exception 'caller is not staff of the source warehouse' using errcode = '42501';
  end if;

  select qty into v_current from public.stock where warehouse_id = p_from for update;

  if v_current is null or v_current < p_qty then
    raise exception 'not enough stock at source (have %)', v_current using errcode = '22003';
  end if;

  update public.stock set qty = qty - p_qty where warehouse_id = p_from;

  if sql%notfound then
    raise exception 'source stock row disappeared' using errcode = '40001';
  end if;

  select exists (select 1 from public.warehouses where id = p_to) into v_dst_exists;

  if not v_dst_exists then
    raise exception 'destination warehouse % does not exist', p_to using errcode = '23503';
  end if;

  update public.stock set qty = coalesce(qty, 0) + p_qty
  where warehouse_id = p_to;

  if sql%notfound then
    insert into public.stock (warehouse_id, sku, qty) values (p_to, p_sku, p_qty);
  end if;

  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (v_from, p_to, p_sku, p_qty, auth.uid());

  return v_current - p_qty;
end
$$;

