create or replace function public.transfer_stock(p_from bigint, p_to bigint, p_sku text, p_qty integer)
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_remaining integer := p_qty;
  v_moved integer;
  v_has_stock boolean;
  v_from_exists boolean;
  v_to_exists boolean;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  p_from := p_from::bigint;
  p_to := p_to::bigint;

  select exists (select 1 from public.warehouses where id = p_from) into v_from_exists;
  if not v_from_exists then
    raise exception 'source warehouse does not exist';
  end if;

  select exists (select 1 from public.warehouses where id = p_to) into v_to_exists;
  if not v_to_exists then
    raise exception 'destination warehouse does not exist';
  end if;

  if p_from = p_to then
    raise exception 'from and to warehouses must differ';
  end if;

  if p_qty is null or p_qty <= 0 then
    raise exception 'quantity must be positive';
  end if;

  if not public.is_warehouse_staff(p_from) then
    raise exception 'only warehouses staff can move stock';
  end if;

  v_has_stock := public.warehouse_has_stock(p_from, p_sku, p_qty);
  if not v_has_stock then
    raise exception 'source % has insuficient stock of %', p_from, p_sku;
  end if;

  update public.stock
    set qty = qty - p_qty
  where warehouse_id = p_from and sku = p_sku;

  if not found then
    raise exception 'source stock not found or modified by concurrent transaction';
  end if;

  insert into public.stock (warehouse_id, sku, qty)
  values (p_to, p_sku, p_qty);

  if not found and p_to is not distinct from p_from then
    raise exception 'destination stock not found or modified by concurrent transaction';
  end if;

  update public.stock
    set qty = qty + p_qty
  where warehouse_id = p_to and sku = p_sku;

  if not found then
    insert into public.stock (warehouse_id, sku, qty) values (p_to, p_sku, p_qty);
  end if;

  if v_to_exists and not exists (select 1 from public.stock where warehouse_id = p_to and sku = p_sku) then
    raise exception 'destination stock row not created';
  end if;

  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (p_from, p_to, p_sku, p_qty, auth.uid());

  return v_remaining;
end;
$$;

