returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_allowed text := case when p_role in ('admin', 'member') then 'Y' else 'N' end;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if p_role not in ('admin', 'member') then
    raise exception 'Invalid role: %', p_role using errcode = '42883';
  end if;

  if p_user_id = v_uid then
    raise exception 'Cannot set your own role' using errcode = '42501';
  end if;

  if v_allowed = 'N' then
    raise exception 'Role out of range' using errcode = '42830';
  end if;

  if not exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = v_uid
      and m.role = 'owner'
  ) and not exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = v_uid
      and m.role = 'admin'
  ) then
    raise exception 'You are not a member of this organization' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = p_user_id
  ) then
    raise exception 'Target is not a member of this organization' using errcode = '42501';
  end if;

  if exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = p_user_id
      and m.role = 'owner'
  ) then
    raise exception 'Cannot change the role of an owner' using errcode = '42501';
  end if;

  update public.org_members
  set role = p_role
  where org_id = p_org_id
    and user_id = p_user_id;

  return p_role;
end;
$$;

