-- Returns TRUE only when they can affect memberships in that org.
--------------------------------------------------------------------
create or replace function public.is_org_owner_or_admin(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
