-- policies
--------------------------------------------------------------------
create policy org_members_select on public.org_members
  for select to authenticated
  using (org_id::text = auth.uid()::text);

create policy leaderboard_select on public.leaderboard
  for select to authenticated
  using (true);

--------------------------------------------------------------------
-- Neither policy is INSERT / UPDATE / DELETE for anon/authenticated
-- (and no other policy exists), so those operations are blocked
-- regardless of RLS being on or off.

--------------------------------------------------------------------
-- set_member_role: restricted RPC
-- Only the function owner has EXECUTE RLS, so it is not RLS-gated
-- but its body is a security definer function that checks membership.
--------------------------------------------------------------------
create or replace function public.set_member_role(
  p_org_id bigint,
  p_user_id uuid,
  p_role text
)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_caller_role text;
  v_target_role text;
begin
  -- valid role?
  if p_role not in ('admin', 'member') then
    raise exception 'Invalid role %', p_role using errcode = '42601';
  end if;

  -- only signed-in users can call
  if auth.uid() is null then
    raise exception 'Only signed-in users can change memberships';
  end if;

  v_caller_role := p_role;

  -- do not target yourself
  if p_user_id = auth.uid() then
    raise exception 'Cannot change your own membership role';
  end if;

  -- do not target owners
  if exists (
    select 1
    from public.org_members
    where org_id = p_org_id
      and user_id = p_user_id
      and role = 'owner'
  ) then
    raise exception 'Cannot demote an organization owner';
  end if;

  -- caller must be a member of the target org
  if not exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
      and m.role in ('owner', 'admin')
  ) then
    raise exception 'You are not a member of this organization';
  end if;

  -- caller must already be an admin or owner
  if not exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
      and m.role = 'owner'
  ) then
    if not exists (
      select 1
      from public.org_members m
      where m.org_id = p_org_id
        and m.user_id = auth.uid()
        and m.role = 'admin'
    ) then
      raise exception 'Only owners and admins can change membership roles';
    end if;
  end if;

  update public.org_members
     set role = p_role
   where org_id = p_org_id
     and user_id = p_user_id
     and exists (
       select 1
       from public.org_members m
       where m.org_id = p_org_id
         and m.user_id = auth.uid()
         and m.role in ('owner', 'admin')
     );

  return set_config('app.member_role', p_role, false);
end;
$$;

