-- recalculate_leaderboard: internal nightly server job
--------------------------------------------------------------------
grant execute on function public.recalculate_leaderboard() to service_role;
revoke execute on function public.recalculate_leaderboard() from anon, authenticated;

---------------------------------------------------------------------------
-- recalculate_leaderboard: recompute scores only from the leaderboard itself
-- (a true idempotent nightly job).  No guard privilege is needed; it
-- runs as the service role.
---------------------------------------------------------------------------
create or replace function public.recalculate_leaderboard()
returns void
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
begin
  update public.leaderboard l
     set score = t.subtotal
   from (
     select coalesce(sum(e.number), 0) as subtotal, e.user_id, e.space_id
     from public.org_members m
     join public.org_members e
       on e.org_id = m.org_id
          and e.user_id <> m.user_id
     where m.org_id is not null
     group by e.user_id, e.space_id
   ) t
  where t.space_id is not null
    and l.user_id = t.user_id;

  -- future: only join leaderboard rows that actually belong to
  -- the caller's organizations, or only keep scores for active members.
  return;
end;
$$;

