-- grants, and by no INSERT/UPDATE/DELETE policies.
revoke all on public.org_members from public;
revoke all on public.leaderboard from public;

grant select on public.org_members to authenticated;
grant select on public.leaderboard to authenticated;

-- R6: server code gets full access; it is RLS-bypassed but the function
-- policies on the underlying tables still apply.
grant all on public.org_members to service_role;
grant all on public.leaderboard to service_role;
