create or replace function public.is_org_member(p_org_id bigint) returns boolean
language sql stable security definer set search_path = '' as
$$
  select exists (select 1 from public.org_members m where m.org_id = p_org_id and m.user_id = auth.uid());
$$;

create or replace function public.org_has_role(p_org_id bigint, p_role text) returns boolean
language sql stable security definer set search_path = '' as
$$
  select exists (select 1 from public.org_members m where m.org_id = p_org_id and m.user_id = auth.uid() and m.role = p_role);
$$;

revoke all on public.is_org_member(bigint) from public, anon;
grant execute on public.is_org_member(bigint) to authenticated, service_role;
revoke all on public.org_has_role(bigint, text) from public, anon;
grant execute on public.org_has_role(bigint, text) to authenticated, service_role;

create policy org_members_select on public.org_members
  for select to authenticated
  using (public.is_org_member(org_id));

create policy leaderboard_select on public.leaderboard
  for select to authenticated
  using (true);

create or replace function public.set_member_role(p_org_id bigint, p_user_id uuid, p_role text) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_role text;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select m.role into v_role
  from public.org_members m
  where m.org_id = p_org_id and m.user_id = v_uid
  for update;

  if not found then
    raise exception 'not a member of target organization';
  end if;

  if p_user_id is distinct from v_uid then
    if v_role <> 'owner' and v_role <> 'admin' then
      raise exception 'only an organization owner or admin may change member roles';
    elsif p_user_id is null or not exists (select 1 from public.org_members m2 where m2.org_id = p_org_id) then
      raise exception 'target user is not a member of the organization';
    elsif exists (select 1 from public.org_members m2 where m2.org_id = p_org_id and m2.user_id = p_user_id) then
      raise exception 'target user is already a member of the organization';
    end if;
  else
    raise exception 'cannot change your own role';
  end if;

  if p_role not in ('admin', 'member') then
    raise exception 'role must be admin or member';
  end if;

  update public.org_members m
     set role = p_role
   where m.org_id = p_org_id and m.user_id = p_user_id;

  return p_role;
end;
$$;

